// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Kişisel finans hesapları: faiz, bütçe, kredi (orta).
const ozEconomics12Orta = <(String, String, List<String>, String)>[
  ('Ahmet 10.000 liralık birikimini yıllık yüzde 10 basit faizle 3 yıllığına, Zeynep ise aynı tutarı yıllık yüzde 10 bileşik faizle aynı süre yatırıyor. 3 yıl sonunda Zeynep\'in hesabı Ahmet\'inkinden kaç lira fazla olur?', '310 lira', ['100 lira', '210 lira', '3.310 lira'], 'Ahmet 13.000, Zeynep 10.000 × 1,331 = 13.310 lira elde eder. Fark 310 liradır.'),
  ('İki banka aynı vadeli ürün için yüzde 12 nominal yıllık faiz ilan ediyor; A faizi yılda bir, B ise her ay bileşik uyguluyor. Mevduat sahibi için hangisi doğrudur?', 'B bankasında efektif getiri daha yüksektir', ['A bankasında efektif getiri daha yüksektir', 'İki bankanın efektif getirisi aynıdır', 'Hangisinin yüksek olduğu anaparaya göre değişir'], 'Aynı nominal oranda bileşikleme sıklığı arttıkça efektif getiri yükselir. B\'nin efektif oranı yaklaşık yüzde 12,68, A\'nınki yüzde 12\'dir.'),
  ('Bir reklamda yalnızca "aylık yüzde 2" gibi aylık oranın verilmesi, tüketicinin ürünleri karşılaştırması açısından neden sorun yaratır?', 'Yıllık efektif karşılığı bilinmeden kıyaslanamaz', ['Aylık oranlar yasal olarak geçerli sayılmaz', 'Aylık oran her zaman yıllık orandan düşük maliyetlidir', 'Aylık faizde anapara hiç geri ödenmez'], 'Aylık yüzde 2 bileşik işlerse yıllık efektif oran yaklaşık yüzde 26,8 olur. Karşılaştırma için ortak bir yıllık efektif oran gerekir.'),
  ('Net yıllık getirisi yüzde 27 olan bir hesapta tutulan para için yıllık enflasyon yüzde 35 ise ne söylenebilir?', 'Reel getiri negatiftir, satın alma gücü azalmıştır', ['Reel getiri pozitiftir, satın alma gücü artmıştır', 'Reel getiri sıfırdır, satın alma gücü sabittir', 'Reel getiri hesaplanamaz çünkü stopaj dikkate alınmaz'], 'Net nominal getiri yüzde 27, enflasyon yüzde 35 olduğundan reel getiri yaklaşık yüzde −6\'dır; para alım gücü kaybetmiştir.'),
  ('Bir kişi 50.000 lirayı yüzde 36 brüt yıllık faizle, yüzde 15 stopajla 1 yıllığına (basit faiz) yatırdı. Vade sonunda eline geçen toplam tutar kaç liradır?', '65.300 lira', ['59.000 lira', '66.000 lira', '68.000,00 lira'], 'Brüt faiz 18.000 lira, stopaj 2.700 lira, net faiz 15.300 liradır. Toplam 65.300 liradır.'),
  ('Bir kişi bugün 10.000 lira ya da 2 yıl sonra 12.000 lira alma seçeneği arasında kalıyor. Hesabında yıllık yüzde 10 bileşik getiri sağlayabiliyorsa hangisi daha kârlıdır?', 'Bugün 10.000 lira; çünkü 2 yıl sonra 12.100 lira eder', ['2 yıl sonra 12.000 lira almak; çünkü tutar daha büyüktür', 'İkisi birbirine eşittir', 'Karşılaştırma yapmak için enflasyon verisi şarttır'], '10.000 lira yüzde 10\'la iki yılda 12.100 liraya ulaşır; bu da 12.000 liradan fazladır. Bu yüzden bugünkü 10.000 lira daha değerlidir.'),
  ('Bir tasarrufçu, paranın bir bölümünü kısa vadeli, bir bölümünü uzun vadeli mevduata bölüp farklı tarihlerde vadesi dolacak şekilde yatırıyor. Bu yönteme verilen ad aşağıdakilerden hangisidir?', 'Vade merdiveni', ['Vade sigortası', 'Faiz takası', 'Karşılık ayırma'], 'Vade merdiveninde farklı vadelere bölünen fonlar belirli aralıklarla çözülür; böylece hem getiri hem likidite dengelenir.'),
  ('Bir kişi vadesiz hesabına gelen maaşı çekmeden aylarca tutuyor. Bu uygulamanın en önemli bedeli nedir?', 'Fırsat getirisi kaybı', ['Banka hesabı kapanacağı için anaparanın kaybedilmesi', 'Her ay otomatik vergi borcu doğması', 'Kredi notunun doğrudan sıfırlanması'], 'Para vadesiz hesapta düşük getirili bekler; getirili aracın sağlayacağı kazanç fırsat maliyetidir.'),
  ('Faiz getirisi için yatırım yapacak bir kişi iki seçenek arasında kalıyor: yıllık yüzde 40 net getirili 6 aylık vade ya da yıllık yüzde 36 net getirili 12 aylık vade. Karar için aşağıdakilerden hangisi mutlaka dikkate alınmalıdır?', 'Toplam getiri ve bağlı kalma süresi', ['Banka şubesinin şehir merkezine uzaklığı', 'Hesabın açıldığı günün adı', 'Banka logosunun rengi'], 'Farklı vadeli ürünlerde karar, ulaşılan toplam getiri ve paranın bloke kalma süresine göre verilir; oranlar yıllıklandırıldığı için süre göz önüne alınmalıdır.'),
  ('Aynı tutar, faiz ve vadede eşit anapara ödemeli kredi ile eşit taksitli kredi karşılaştırılırsa hangisi doğrudur?', 'Toplam faiz daha düşük, ilk taksitler daha yüksektir', ['Eşit anapara ödemelide toplam faiz daha yüksektir ve ilk taksitler daha düşüktür', 'İkisinde de toplam faiz ve taksitler tamamen aynıdır', 'Eşit taksitlide toplam faiz daha düşüktür ve ilk taksit daha yüksektir'], 'Eşit anapara ödemelide borç daha hızlı eridiği için toplam faiz azdır; fakat başlangıç taksitleri eşit taksitliden yüksek olur.'),
  ('Aylık geliri düşük ve nakit akışı başlangıçta kısıtlı bir ailenin eşit anapara ödemeli kredi yerine eşit taksitli krediyi seçmesinin en güçlü nedeni nedir?', 'Başlangıç taksit yükü daha düşük olur', ['Toplam faiz her zaman çok daha düşük olur', 'Banka faiz oranını sıfırlar', 'Anapara hiç ödenmez'], 'Eşit taksitlide taksit sabit ve genelde ilk taksitler eşit anaparalıya göre düşüktür; bu, nakit akışı kısıtlı hanehalkı için kolaylık sağlar.'),
  ('Bir bankanın "yıllık maliyet oranı" (efektif maliyet) hesabında faiz dışında hangi kalemler de dikkate alınır?', 'Dosya masrafı ve sigorta', ['Yalnızca müşterinin maaş tutarı', 'Bankanın şube sayısı', 'Müşterinin yaşadığı şehrin nüfusu'], 'Efektif maliyet, borçlunun gerçek maliyetini göstermek için faize ek olarak krediyle birlikte alınan masraf ve sigortaları da içerir.'),
  ('Bir kişi 3 yıl vadeli kredisini 2. yılın sonunda erken kapatıyor. Genel olarak erken ödemenin sonucu aşağıdakilerden hangisidir?', 'Kalan vade faizi ödenmez, maliyet düşer', ['Banka kalan faizin tamamını aynen tahsil eder', 'Toplam maliyet kesinlikle iki katına çıkar', 'Kredi notu otomatik olarak sıfırlanır'], 'Erken kapamada kalan anapara ödenir; ileri vadeli faizler hesaplanmadığı için toplam maliyet azalır. Bazı kredilerde makul bir erken ödeme tazminatı alınabilir.'),
  ('Erken ödeme tazminatı alınan bir krediyi kapatmayı düşünen kişi karar vermeden önce hangisini karşılaştırmalıdır?', 'Tazminatı ve faiz tasarrufunu', ['Bankanın yıllık bilanço kâr tutarını', 'Ay isimlerinin gün sayılarını', 'Bankanın şubesindeki bekleme süresini'], 'Erken kapama yalnızca tasarruf edilen faiz ödenecek tazminattan fazlaysa kâr getirir. Bu yüzden iki tutar kıyaslanmalıdır.'),
  ('Değişken faizli bir konut kredisi kullanan kişi piyasa faizlerinin düşeceğini bekliyor. Bu beklenti ona göre hangi yönde değerlendirme yapılmasına neden olur?', 'Taksitler azalabileceği için değişken faizi avantajlı görür', ['Faizler düşerken taksitlerin kesinlikle artacağını düşünür', 'Faizler düşse de kredi faizinin hiç değişmeyeceğini düşünür', 'Konut kredisi kullanmanın imkânsız olacağını düşünür'], 'Değişken faizli kredide faiz, referans orana göre güncellenir; faizler düşerse borçlunun taksit yükü de azalabilir. Ters yönde hareket riski de vardır.'),
  ('Bir kişi ilk evini alırken konut fiyatının yüzde 90\'ı kadar kredi kullanmak istiyor. Bu oran için bankanın genel yaklaşımı ve borçlunun riski hakkında hangisi doğrudur?', 'Kredi/değer oranı arttıkça borçlunun ödeme riski artar', ['Oran yükseldikçe risk azalır, çünkü kredi daha büyüktür', 'Kredi/değer oranının risk üzerinde hiçbir etkisi yoktur', 'Banka bu durumda faizi her zaman sıfırlar'], 'Kredi/değer oranı yüksekse borçlunun kendi katkısı azdır; konutun değeri düşerse bankanın alacağı güvencesiz kalabilir. Bu yüzden genellikle sınırlar uygulanır.'),
  ('Bir kişi 600.000 liralık aracı 3 yıl sonra 360.000 liraya satabilecek. Bu 3 yıllık süredeki toplam değer kaybı ve ortalama yıllık değer kaybı kaç liradır?', 'Toplam 240.000, yıllık ortalama 80.000 lira', ['Toplam 360.000, yıllık ortalama 120.000 lira', 'Toplam 240.000, yıllık ortalama 120.000 lira', 'Toplam 600.000, yıllık ortalama 200.000 lira'], 'Değer kaybı = 600.000 − 360.000 = 240.000 liradır; üç yıla bölünürse yıllık ortalama 80.000 lira bulunur.'),
  ('Haftada yalnızca iki kez kısa mesafe kullanılan bir otomobilin yıllık sabit giderleri (sigorta, vergi, değer kaybı) yüksekse, kişinin hangi alternatifi değerlendirmesi mantıklıdır?', 'Taksi ya da araç paylaşımı', ['Aracın sigortasını tamamen iptal etmek', 'Daha pahalı ikinci bir araç almak', 'Her yıl aracı yenisiyle değiştirmek'], 'Düşük kullanımda sabit maliyetler yoğun olduğundan kullandığın kadar öde seçenekleri toplam maliyeti düşürebilir.'),
  ('Taşıt kredisinde araç, taksitler ödenene kadar bankanın alacağı için güvence işlevi gören hangi kayıtla sınırlandırılabilir?', 'Rehin şerhi', ['Hapis cezası kaydı', 'Sicil affı', 'Vergi levhası'], 'Taşıt kredilerinde alacak, aracın trafik tescil kaydına işlenen rehin şerhiyle güvence altına alınır; borç bitince şerh kaldırılır.'),
  ('Bir hanenin vadesiz hesaplarında ve para piyasası fonunda toplam 54.000 lira vardır; aylık zorunlu giderleri 18.000 liradır. Likidite oranı (likit varlık ÷ aylık zorunlu gider) kaçtır ve ne anlama gelir?', '3; gelir kesilirse yaklaşık üç ay karşılanır', ['0,33; gelirin üçte biri tasarruf edilmektedir', '3; hane her ay üç kat fazla harcamaktadır', '0,33; borçların üçte biri ödenmiştir'], '54.000 ÷ 18.000 = 3\'tür. Oran, likit varlıkların gelir olmadan kaç ay zorunlu gideri karşılayabileceğini gösterir.'),
  ('Toplam varlıkları 1.200.000 lira, toplam borçları 450.000 lira olan bir ailenin net değeri ile varlıklarının ne kadarının kendi öz kaynağı olduğu (net değer ÷ toplam varlık) hangisidir?', '750.000 lira; yüzde 62,5', ['750.000 lira; yüzde 37,5', '450.000 lira; yüzde 37,5', '1.650.000 lira; yüzde 137,5'], 'Net değer = 1.200.000 − 450.000 = 750.000 liradır. Oran 750.000 ÷ 1.200.000 = yüzde 62,5\'tir.'),
  ('Bir kişi birikimindeki 100.000 lirayı kullanarak aynı tutarda kredi borcunu peşin kapatıyor. Başka hiçbir değişiklik olmazsa kişisel net değeri ilk anda nasıl değişir?', 'Değişmez; hem varlık hem borç aynı tutarda azalır', ['100.000 lira artar; çünkü borç silinmiştir', '100.000 lira azalır; çünkü birikim eksilmiştir', '200.000 lira artar; çünkü borç ve birikim birlikte yok olur'], 'Net değer = varlıklar − borçlar. İkisi de 100.000 lira azaldığı için fark değişmez; ancak sonraki faiz giderleri ortadan kalkar.'),
  ('Yıllık 14.400 lira tutarındaki trafik ve kasko primi her yıl Mart ayında tek seferde ödeniyor. Düzenli bütçe yapan biri bu gider için aylık ne kadar ayırmalıdır?', '1.200 lira', ['14.400 lira', '2.400 lira', '600 lira'], 'Yıllık düzensiz gider 12\'ye bölünerek aylık karşılık ayrılır: 14.400 ÷ 12 = 1.200 lira. Buna "yıllık gider fonu" ya da "birikim kalemi" denir.'),
  ('Yılda bir ödenen sigorta primi, okul taksiti veya bakım gibi düzensiz giderler için aylık küçük tutarlar ayırıp ayrı bir hesapta biriktirme uygulamasına ne ad verilir?', 'Sinking fund', ['Likidite tuzağı', 'Vade merdiveni', 'Zorunlu karşılık'], 'Amaca yönelik ara fon, bilinen ama düzensiz giderler için önceden küçük küçük para ayırma yöntemidir; bütçe şoklarını azaltır.'),
  ('Bir ay için 8.000 lira market bütçesi belirlenen ailenin gerçek market harcaması 9.200 lira olmuştur. Bütçe sapması ve yorumu nedir?', '1.200 liralık olumsuz sapma; plandan yüzde 15 fazla', ['1.200 liralık olumlu sapma; harcama plandan yüzde 15 fazla', '1.200 liralık olumsuz sapma; harcama plandan yüzde 13 fazla', '9.200 liralık olumlu sapma; harcama plana uygun'], 'Gerçekleşen − planlanan = 1.200 liradır; harcama bütçeyi aştığı için sapma olumsuzdur. Oran 1.200 ÷ 8.000 = yüzde 15\'tir.'),
  ('Bir kişi yeni maaş zammıyla birlikte her kalemde harcamasını artırıp ek geliri tamamen tüketiyor. Davranışsal finansta bu duruma ne ad verilir?', 'Yaşam tarzı şişmesi', ['Likidite tuzağı etkisi', 'Kayıptan kaçınma', 'Ahlaki tehlike'], 'Gelir artışı kadar giderlerin de yükselmesi, kişinin birikim gücünün gelire rağmen artmamasına yol açar.'),
  ('Bir kişinin aylık düzenli nakit girişi 30.000 lira, düzenli nakit çıkışı 33.500 liradır. Bu durumun sürmesi halinde en olası sonuç nedir?', 'Birikim erir veya borç artar', ['Net değer kendiliğinden artar', 'Bütçe fazlası oluşur', 'Borç otomatik olarak silinir'], 'Aylık 3.500 liralık nakit açığı karşılanmazsa birikim tüketilir ya da yeni borç alınır; nakit akışı dengelenmelidir.'),
  ('Bütçe oluştururken gelir ve giderlerin son üç aylık ortalamasını esas alan bir kişi bu yolla ne elde etmeyi amaçlar?', 'Gerçekçi bir ortalama temel', ['Gelecekteki faiz oranlarını kesin bilmek', 'Vergi borcunu sıfırlamak', 'Kredi kartı limitini artırmak'], 'Birkaç aylık ortalama, geçici dalgalanmaları yumuşatır; bu sayede planlama gerçeğe daha yakın veriye dayanır.'),
  ('Hesap kesim tarihi ayın 5\'i, son ödeme tarihi ayın 15\'i olan kartla 6 Haziran\'da yapılan alışverişin ödeme tarihi hangisidir?', '15 Temmuz', ['15 Haziran', '5 Temmuz', '5 Ağustos'], '6 Haziran harcaması 5 Haziran kesiminden sonra olduğu için 5 Temmuz\'da kesilecek ekstreye girer; son ödeme tarihi 15 Temmuz\'dur.'),
  ('Kart puanı karşılığında alışveriş sonrası yüzde 1 puan kazanan bir kişi ekstre borcunu asgari ödemeyle uzatıyor ve aylık yüzde 4 faiz ödüyor. Bu durumun sonucu nedir?', 'Faiz maliyeti puan getirisinden çok yüksektir', ['Puan kazancı faiz maliyetini karşılar', 'Faiz kazanılan puana eşit olduğundan fark yoktur', 'Puanlar faizi tamamen siler'], 'Yüzde 1\'lik puan getirisi, aylık yüzde 4\'lük faiz yanında çok küçüktür; borç taşıyan kullanıcı net zarar eder.'),
  ('Bir kişi, hiç borcu olmasa da kart başvurularını kısa sürede birçok bankaya yapıyor. Bu davranışın kredi notuna olası etkisi nedir?', 'Sık sorgu notu düşürebilir', ['Başvuru sayısı notu otomatik yükseltir', 'Bankalar başvuruları hiç kaydetmez', 'Not yalnızca gelirine göre belirlenir'], 'Kısa sürede çok sayıda kredi başvurusu, borç arayışı sinyali olarak algılanır ve kredi puanını olumsuz etkileyebilir.'),
  ('Kredi kartı limitinin yarısından fazlasını sürekli kullanan ama ödemelerini geciktirmeyen biri için en uygun öneri nedir?', 'Kullanım oranını düşürmek', ['Limiti sürekli sonuna kadar kullanmak', 'Tüm kartları aynı gün iptal etmek', 'Düzenli ödemeyi bırakıp tek seferde ödemek'], 'Kullanılan limitin toplam limite oranı düşük tutulduğunda kredi notu genellikle iyileşir.'),
  ('Yeni bir kredi geçmişi olmayan genç bir çalışanın kredi puanını sağlıklı biçimde oluşturabilmesi için en makul yol hangisidir?', 'Küçük borçları düzenli ödemek', ['Hiç borçlanmayıp tek kuruş harcamamak', 'Bir ay içinde birçok kredi çekmek', 'Ödemeleri geciktirip sonra toplu ödemek'], 'Kredi notu ödeme davranışından beslenir. Küçük ve kontrol edilebilir borçları düzenli ödemek olumlu geçmiş yaratır.'),
  ('Bir kişi ödemediği borç nedeniyle hakkında icra takibi başlatılan bir alacaklıya karşı hangi sonuçla karşılaşabilir?', 'Haciz uygulanabilir', ['Tüm borçları otomatik olarak silinir', 'Faiz oranı sıfıra düşer', 'Kredi notu en yüksek seviyeye çıkar'], 'İcra takibinde alacaklı, yasal sınırlar çerçevesinde malvarlığı ve maaş üzerinde haciz isteyebilir; bu durum kredi notunu da ciddi düşürür.'),
  ('Bir kişinin üç borcu var: 5.000 lira ve yıllık yüzde 20; 30.000 lira ve yıllık yüzde 45; 12.000 lira ve yıllık yüzde 30. Faiz maliyetini en aza indirmeyi hedefliyorsa ek ödemeyi önce hangisine yöneltmelidir?', '30.000 liralık, yüzde 45 faizli borca', ['5.000 liralık, yüzde 20 faizli borca', '12.000 liralık, yıllık yüzde 30 faizli borca', 'Üçüne eşit dağıtarak'], 'Çığ yönteminde ek ödeme en yüksek faizli borca yönelir. Böylece toplam faiz yükü matematiksel olarak en çok azalır.'),
  ('Aynı üç borç için psikolojik açıdan hızlı başarı hissi isteyen biri hangi borcu ilk kapatmayı seçer?', 'En düşük bakiyeli 5.000 liralık borcu', ['En yüksek faizli 30.000 liralık borcu', 'En uzun vadeli olan ve en yüksek taksitli borcu', 'Yalnızca kredi kartı olmayan borcu'], 'Kartopu yönteminde küçük bakiyeli borç hızla kapanır; bu görünür başarı motivasyonu artırır, ancak faiz maliyeti çığa göre biraz yüksek olabilir.'),
  ('Kredi kartı borcunu ödemek için bir başka karttan nakit avans çeken kişinin içine düştüğü durum nasıl adlandırılır?', 'Borcu borçla çevirme', ['Borç silme', 'Konsolidasyonun en güvenli biçimi', 'Vade merdiveni'], 'Nakit avansın faizi yüksek olduğundan borç kapanmaz, yalnızca ertelenir ve büyür; bu sarmal ciddi bir mali risk doğurur.'),
  ('Taksit ödemelerinde zorlanan bir borçlunun bankasıyla yeniden vade uzatma görüşmesi yapmasının kısa vadeli faydası ve bedeli hangisidir?', 'Aylık yük azalır, toplam faiz artabilir', ['Aylık yük artar ama toplam faiz azalır', 'Aylık yük ve toplam faiz birlikte azalır', 'Borç hiç ödenmeden kapanır'], 'Vadenin uzatılması taksiti küçültür; ancak borç daha uzun süre kaldığı için toplam ödenen faiz büyür.'),
  ('Ayıplı mal aldığını fark eden bir tüketici, 6502 sayılı Kanun\'a göre aşağıdaki seçimlik haklardan hangisini kullanamaz?', 'Cezai tazminat istemek', ['Satış bedelinden ayıp oranında indirim istemek', 'Malın ücretsiz onarılmasını istemek', 'Ayıpsız misliyle değiştirilmesini istemek'], 'Tüketicinin seçimlik hakları sözleşmeden dönme, bedel indirimi, ücretsiz onarım ve ayıpsız misliyle değişimdir. Cezai tazminat bu haklardan biri değildir.'),
  ('Aldığı cep telefonunun garanti süresi içinde birkaç kez arızalanan Selim, satıcı onarımı yapmadığı için hangi kuruma başvurabilir?', 'Tüketici Hakem Heyeti', ['Sermaye Piyasası Kurulu', 'Rekabet Kurumu', 'Borsa İstanbul'], 'Tüketici uyuşmazlıkları, parasal sınırlara göre Tüketici Hakem Heyetleri ya da Tüketici Mahkemelerinde çözülür.'),
  ('Satıcının, taksitli satışta uygulanan faiz oranını ve toplam ödenecek tutarı sözleşmede açıkça belirtmesi gerekliliği tüketiciye hangi hakkı sağlar?', 'Maliyeti kıyaslayıp bilinçli karar verebilme', ['Ürünü ücretsiz alabilme', 'Faizsiz ödeme zorunluluğu', 'Sözleşmeden her halükârda ceza almadan çıkma'], 'Maliyet bilgisinin açık verilmesi, tüketicinin peşin fiyat ile vadeli toplam bedeli kıyaslamasını mümkün kılar.'),
  ('Düzenli tasarruf yapmak isteyen biri maaşının bir bölümünü gelir yattığı gün otomatik olarak birikim hesabına aktaracak talimat veriyor. Bu uygulama hangi davranışsal eğilime karşı bir önlemdir?', 'Ertelemeye yatkınlık', ['Fazla iyimser enflasyon beklentisi', 'Tüketici güveninin yüksekliği', 'Vergi kaçınma isteği'], 'Otomatik transfer, iradeye bağımlılığı azaltır; kişinin gelirini harcamadan önce birikime ayırmasını sağlar.'),
  ('Harcamalarını izlemeyen bir kişi, yıl sonu hesabında sürekli beklediğinden fazla harcadığını görüyor. Bu durum hangi davranışsal eğilimle açıklanır?', 'Planlama yanılgısı', ['Para yanılsaması: reel değerleri nominal sanma', 'Sürü davranışı: başkalarını izleme', 'Sahiplik etkisi: eşyaya fazla değer biçme'], 'İnsanlar gelecekteki giderlerini ve süreleri iyimser tahmin eder; harcama kaydı tutmak bu önyargıyı azaltır.'),
  ('Moda ürünlerde "bu hafta sonuna kadar yüzde 70 indirim" afişini gören ama zaten ihtiyacı olmayan bir tüketici için en rasyonel karar hangisidir?', 'İhtiyacı ve gerçek fiyatı sorgulamak', ['İndirim yüzde 70 olduğu için her koşulda satın almak', 'Birkaç tane alıp fazla kısmı stoklamak', 'Kredi kartı limitini artırıp alışverişi büyütmek'], 'İndirim yalnızca ihtiyaç varsa tasarruf sağlar. Gerçek fiyat ve ihtiyaç sorgulanmazsa harcama artar.'),
  ('Varsayımsal bir vergi tarifesinde yıllık gelirin ilk 100.000 lirası yüzde 15, sonraki 150.000 lirası yüzde 20, daha fazlası yüzde 27 oranında vergilendiriliyor. Yıllık 180.000 lira vergi matrahı olan birinin ödeyeceği vergi kaç liradır?', '31.000 lira', ['36.000 lira', '27.000 lira', '48.600,00 lira'], 'İlk 100.000 liranın vergisi 15.000, kalan 80.000 liranın vergisi 80.000 × 0,20 = 16.000 liradır. Toplam 31.000 liradır.'),
  ('Aylık brüt maaşın kümülatif gelir vergisi matrahı yıl boyunca birikir. Bu durum maaşı yıl içinde nasıl etkileyebilir?', 'Üst dilime girildikçe net maaş azalabilir', ['Net maaş aylık sabit kaldığı için hiç değişmez', 'Yıl sonunda tüm vergi iade edilir', 'Matrah sıfırlandığı için net maaş yıl boyunca artar'], 'Gelir vergisi matrahı yıl içinde birikir. Üst dilime girildiğinde kesilen vergi artar ve net maaş düşebilir; yeni yılda dilimler yeniden başlar.'),
  ('KDV dahil fiyatı 7.200 lira olan ürünün yüzde 20 KDV oranıyla KDV hariç fiyatı ve KDV tutarı hangisidir?', 'Hariç fiyat 6.000, KDV 1.200 lira', ['Hariç fiyat 5.760, KDV 1.440 lira', 'Hariç fiyat 6.480, KDV 720 lira', 'Hariç fiyat 7.200 lira, KDV 1.440 lira'], '7.200 ÷ 1,20 = 6.000 lira hariç fiyattır. KDV 7.200 − 6.000 = 1.200 liradır.'),
  ('KDV dahil 3.960 lira olan ve yüzde 10 KDV\'ye tabi bir hizmetin KDV tutarı kaç liradır?', '360 lira', ['396,50 lira', '324 lira', '400 lira'], 'KDV hariç bedel 3.960 ÷ 1,10 = 3.600 liradır; KDV 360 liradır. Yüzde 10\'u dahil fiyattan almak (396 lira) yanlıştır.'),
  ('Dolaylı vergilerin dar gelirli hanelerin bütçesine göreli yükü neden daha ağır olabilir?', 'Gelirinin büyük kısmını tükettikleri için', ['Gelirlerinin tamamını tasarruf ettikleri için', 'Gelir vergisi dilimlerinin üst sınırına girdikleri için', 'Hiç tüketim yapmadıkları için'], 'Düşük gelirli hane gelirinin büyük bölümünü harcar; tüketim vergileri bu yüzden gelirlerinde daha büyük pay tutar. Bu duruma gerileyici etki denir.'),
  ('Türkiye\'de yıllık gelir vergisi beyannamesi hangi ayda verilir ve genellikle ödeme nasıl yapılır?', 'Mart ayında; Mart ve Temmuz\'da iki taksitle', ['Ocak ayında verilir; vergi Ocak\'ta tek seferde ödenir', 'Haziran ayında verilir; vergi Aralık\'ta ödenir', 'Eylül ayında verilir; vergi peşin ödenir'], 'Yıllık gelir vergisi beyannamesi izleyen yılın Mart ayı içinde verilir; vergi Mart ve Temmuz aylarında iki eşit taksitte ödenir.'),
  ('Serbest meslek makbuzu kesen biri yüzde 20 stopajlı 10.000 liralık bir iş yaptı. Müşteri kendisine kaç lira öder ve geri kalan neden kesilmiştir?', '8.000 lira öder; 2.000 lira stopajdır', ['10.000 lira öder; stopaj sonradan iade edilir', '8.000 lira öder; 2.000 lira banka komisyonudur', '12.000 lira öder; 2.000 lira KDV\'dir'], 'Müşteri, ödeme sırasında yüzde 20 stopajı keserek vergi dairesine yatırır; serbest çalışan yıl sonu beyannamesinde bu tutarı mahsup eder.'),
  ('Geliri düzensiz olan serbest çalışan, stopajı kesilmiş ödemeler alıyorsa yıllık beyannamede stopaj için ne yapar?', 'Stopajı yıllık vergiden mahsup eder', ['Stopajı hesaplamaya katmaz', 'Stopajı bankaya fatura eder', 'Stopaj tutarını başka kişiye devreder'], 'Kesilen stopaj, kişinin yıllık gelir vergisi borcuna peşin ödeme sayılır; fazla ise iade alınabilir.'),
  ('Aynı evin saf primi 2.000 lira iken şirket yönetim gideri ve kâr payı için yüzde 40 yükleme yapıyorsa müşteri yıllık kaç lira prim öder?', '2.800 lira', ['2.400 lira', '3.200 lira', '4.000,50 lira'], 'Yükleme saf primin yüzde 40\'ıdır: 2.000 × 1,40 = 2.800 liradır. Prim hiçbir zaman saf primden küçük olmaz.'),
  ('Aynı otomobili aynı riske karşı iki farklı şirketten sigortalatan bir kişi hasar halinde en çok ne kadar tazminat alabilir?', 'Gerçek zararı kadar', ['Her şirketten ayrı ayrı tam bedel', 'Poliçelerin toplamının iki katı', 'Hiçbir şirketten tazminat alamaz'], 'Çifte sigortada toplam tazminat gerçek zararı aşamaz; şirketler zararı aralarında paylaşır.'),
  ('Bir kişi evini yangına karşı sigortalatmak yerine, her ay küçük bir tutarı kenara ayırarak olası hasarı kendisi karşılamayı seçiyor. Risk yönetimi açısından bu seçim hangisidir?', 'Riski kabul etme', ['Riski sigortacıya aktarma', 'Riskten tamamen kaçınma', 'Riski başkasına bağışlama'], 'Riskin kendi kaynaklarla karşılanması "kabul" yöntemidir. Büyük kayıp riskinde yetersiz kalabileceğinden dikkatli kullanılmalıdır.'),
  ('Sigara içmeyi bırakmak, evde yangın alarmı kurmak ve trafikte emniyet kemeri takmak risk yönetiminde hangi yönteme girer?', 'Riski azaltma', ['Riski aktarma', 'Riski kabul etme', 'Riskten kaçınma'], 'Bu davranışlar riskin gerçekleşme olasılığını ya da etkisini küçültür; böylece olası kayıp azalır.'),
  ('Yalnızca belirli bir süre boyunca, örneğin 20 yıl, sigortalının ölümünde ödeme yapan ve birikim oluşturmayan hayat sigortası türü hangisidir?', 'Süreli hayat sigortası', ['Birikimli hayat sigortası', 'Ömür boyu emeklilik sigortası', 'Konut sigortası'], 'Süreli hayat sigortası yalnız ölüm teminatı verir; vade sonunda sağ kalınırsa ödeme olmaz. Bu yüzden primi düşük olur.'),
  ('Aynı yaş ve teminatta birikimli hayat sigortasının primi, süreli hayat sigortasına göre neden genellikle daha yüksektir?', 'Birikim payı da içerdiği için', ['Sadece vergi uygulandığı için', 'Sigortalı daha genç olduğu için', 'Poliçe süresi kısa olduğu için'], 'Birikimli sigortada primin bir bölümü yatırıma ayrılır; vade sonunda toplu bir ödeme olur. Bu nedenle prim yüksektir.'),
  ('Bir hanede tek gelir sahibi olan, ayrıca çocukları ve kredisi bulunan kişi için hayat sigortasındaki teminat tutarı genel olarak nasıl belirlenmelidir?', 'İhtiyaç ve borç kadar teminat', ['Mümkün olan en düşük tutarda', 'Yalnızca ödeyeceği vergi kadar', 'Komşuların aldığı tutarın aynısı kadar'], 'Hayat sigortasının amacı, gelir sahibinin ölümünde bakmakla yükümlü olduğu kişilerin yaşam standardını ve borç yükünü karşılamaktır.'),
  ('Kamu aylığı yüzde 50 ikame sağlayacak bir çalışan yüzde 80 yaşam standardı hedefliyorsa kalan farkı ne kadar bireysel gelir sağlamalıdır?', 'Son gelirin yüzde 30\'unu', ['Son gelirin yüzde 80\'ini', 'Son gelirin yüzde 50\'sini', 'Son gelirin yüzde 130\'unu'], 'Hedef yüzde 80, kamu aylığı yüzde 50 olduğundan fark 80 − 50 = yüzde 30\'dur.'),
  ('İşsizlik ödeneğinden yararlanmak için son üç yıl içinde en az kaç gün işsizlik sigortası primi ödenmiş olmalıdır?', '600 gün', ['300 gün', '900 gün', '1.800 gün'], 'İşsizlik ödeneği için işten ayrılmadan önceki 3 yıl içinde en az 600 gün prim, son 120 günde de kesintisiz sigortalılık aranır.'),
  ('İşveren tarafından haksız yere işten çıkarılan ve 2 yıl çalışmış olan bir işçi, iş sözleşmesinin bildirim süresine uyulmadan feshedilirse hangi tazminatı da talep edebilir?', 'İhbar tazminatı', ['Eğitim tazminatı', 'Vergi iadesi', 'Faiz tazminatı'], 'İhbar süresine uyulmadan yapılan fesihte işçi, bildirim süresine ait ücreti ihbar tazminatı olarak talep edebilir.'),
  ('İş Kanunu\'nda çalışma süresi 6 ay ile 1,5 yıl arasında olan bir işçi için işverenin uyması gereken bildirim (ihbar) süresi kaç haftadır?', '4 hafta', ['2 hafta', '6 hafta', '8 hafta'], 'Bildirim süreleri kıdeme göre artar: 6 aydan az 2, 6 ay-1,5 yıl 4, 1,5-3 yıl 6, 3 yıldan fazla 8 haftadır.'),
  ('Peşinatı için 1.000.000 lirası olan bir aile, bu parayı yıllık yüzde 30 net getiri sağlayan bir araçta değerlendirebiliyorsa evi peşin almanın yıllık fırsat maliyeti nedir?', '300.000 lira', ['30.000 lira', '100.000 lira', '1.000.000 lira'], 'Fırsat maliyeti, paranın başka yerde sağlayacağı getiridir: 1.000.000 × 0,30 = 300.000 lira.'),
  ('Bir kiracı ile ev sahibi arasında, yeni kira döneminde kira artışının üst sınırı Türk Borçlar Kanunu\'nda neye göre belirlenmiştir?', 'Önceki 12 ayın TÜFE ortalaması', ['Merkez bankası politika faizi', 'Bir önceki yılın dolar kuru ortalaması', 'Yıllık asgari ücret artış oranı'], 'Türk Borçlar Kanunu md. 344\'e göre yenilenen kira dönemlerinde artış oranı, önceki 12 aya ilişkin TÜFE ortalamasını aşamaz.'),
  ('Kirada oturan biri, kira yerine ev almanın gerçek yıllık maliyetini hesaplarken aşağıdakilerden hangisini mutlaka eklemelidir?', 'Faiz, vergi ve bakım', ['Yalnızca evin etiket fiyatı', 'Yalnızca tapu devir tarihi', 'Yalnızca komşuların kira bedelleri'], 'Sahip olmanın maliyeti etiket fiyatının ötesinde; faiz, vergi, bakım ve peşinatın fırsat getirisini içerir. Evin değer artışı ise gelir kalemidir.'),
  ('Beş yıl içinde taşınma ihtimali yüksek olan bir kişi için ev almanın kiralamaya göre başlıca riski hangisidir?', 'İşlem masrafları getiriyi eritebilir', ['Kiralamanın hiçbir riski olmaması', 'Konut fiyatlarının kesinlikle hızla artması', 'Kira ödemenin vergiden muaf olması'], 'Tapu harcı, komisyon ve olası fiyat düşüşü gibi işlem maliyetleri uzun vadede yayılır; kısa süre sahip olunursa kâr getirisini aşabilir.'),
  ('Düzenli aralıklarla sabit tutarda yatırım yapma yönteminin tek seferde tüm parayı yatırmaya göre başlıca faydası nedir?', 'Zamanlama riskini azaltması', ['Her koşulda daha yüksek getiri garanti etmesi', 'Vergi oranını sıfırlaması', 'Riski tamamen ortadan kaldırması'], 'Düzenli yatırım, alım zamanlamasını yayarak fiyat dalgalanmasının etkisini yumuşatır ama getiri garantisi vermez.'),
  ('Üç ay içinde bir kira depozitosu ödemesi yapacak biri için paranın değerlendirileceği aracın seçiminde hangi ölçüt en önemlidir?', 'Anapara koruma ve likidite', ['Mümkün olan en yüksek getiri beklentisi', 'En uzun vade', 'En yüksek dalgalanma'], 'Kısa vadeli ve bilinen bir ödeme için likidite ve sermayenin korunması getiriden önce gelir; riskli araçlarda zarar etme olasılığı yüksektir.'),
  ('Yatırım yaparken "yüksek getiri vaadi" ile "düşük risk vaadi"nin birlikte sunulması neden şüpheli sayılır?', 'Yüksek getiri genelde yüksek riskle gelir', ['Yüksek getiri yalnızca devlet garantili ürünlerde olur', 'Risk ve getiri birbirinden tamamen bağımsızdır', 'Düşük risk her zaman yüksek getiri demektir'], 'Risk ve beklenen getiri arasında pozitif ilişki vardır. Birlikte vaat edilen yüksek getiri ve düşük risk, dolandırıcılık işareti olabilir.'),
  ('Gelirinin büyük kısmını kira ve gıdaya harcayan bir haneyle, gelirinin büyük kısmını eğlence ve seyahate harcayan bir haneyi aynı enflasyon şoku etkilediğinde ilk haneye daha ağır yansıma olmasının nedeni nedir?', 'Zorunlu harcamalar ertelenemediği için', ['Bu harcamaların vergiden muaf olduğu için', 'Eğlence harcamalarının sıfır enflasyonlu olduğu için', 'Gıdada fiyatların her zaman düştüğü için'], 'Temel ihtiyaçlar vazgeçilmez olduğundan fiyat artışı doğrudan bütçeyi sıkıştırır; isteğe bağlı harcama ise ertelenebilir.'),
  ('Bir kişi dolar, altın ve gayrimenkul gibi araçlarla enflasyondan korunmayı hedeflerken hangi gerçeği göz ardı etmemelidir?', 'Bu araçların fiyatları da düşebilir', ['Bu araçlar daima enflasyonun üzerinde getiri sağlar', 'Bu araçlar hiçbir koşulda değer kaybetmez', 'Bu araçların vergisi kanunen sıfırdır'], 'Enflasyondan korunma amaçlı varlıklar da fiyat dalgalanması yaşar; kısa dönemde değer kaybedebilir.'),
  ('Kendini banka görevlisi olarak tanıtan bir kişi telefonda hesabınıza kimsenin girmediğini doğrulamak için kart bilgilerinizi ve SMS ile gelen kodu istiyor. Bu dolandırıcılık yöntemi hangi adla bilinir?', 'Telefonla oltalama', ['Kaldıraçlı alım satım', 'Faiz takası', 'Zorunlu karşılık'], 'Vishing, telefon aracılığıyla sosyal mühendislikle bilgi çalma yöntemidir. Bankalar müşteriden tek kullanımlık kodları telefonla istemez.'),
  ('Kişinin telefon numarası kendisinin haberi olmadan başka bir SIM karta aktarılırsa dolandırıcının hangi riski artırması mümkündür?', 'Doğrulama kodlarını ele geçirmesi', ['Kredi kartı limitini kendi kendine düşürmesi', 'Faiz oranını sıfırlaması', 'Hesabı vergiden muaf kılması'], 'SIM kart takasında kod SMS\'leri dolandırıcının telefonuna gider; hesap ele geçirme riski artar. Operatörden hat kesilmesi alarm işaretidir.'),
  ('Yatırım danışmanlığı yaptığını söyleyen ve sosyal medyadan "garantili yüzde 20 aylık getiri" vaat eden kişinin güvenilirliği için en önemli kontrol hangisidir?', 'SPK\'dan faaliyet izni olup olmadığına bakmak', ['Profil fotoğrafının profesyonel olup olmadığına bakmak', 'Takipçi sayısının yüksekliğine bakmak', 'Mesajın saatine bakmak'], 'Yatırım danışmanlığı izne tabidir. İzinsiz kişilerin "garantili getiri" vaatleri çoğunlukla dolandırıcılık göstergesidir.'),
  ('Lusardi ve Mitchell\'in finansal okuryazarlık ölçümündeki sorulardan birinde tasarruf hesabı yıllık yüzde 1 faiz verirken enflasyon yüzde 2\'dir. Bir yıl sonra bu parayla bugünkü kadar mal alınabilir mi?', 'Hayır, bugünkünden daha azı alınabilir', ['Evet, tam olarak aynısı alınabilir', 'Evet, bugünkünden daha fazlası alınabilir', 'Cevap anaparanın büyüklüğüne bağlıdır'], 'Faiz getirisi enflasyondan düşük olduğu için reel getiri negatiftir; paranın alım gücü azalır.'),
  ('Lusardi ve Mitchell\'in finansal okuryazarlık ölçeğinde "tek bir şirketin hissesi mi, yoksa çok sayıda hisseden oluşan fon mu daha az risklidir" sorusunun doğru yanıtı nedir?', 'Çok hisseli fon daha az risklidir', ['Tek şirketin hissesi daha az risklidir', 'İkisi aynı riske sahiptir', 'Fon her zaman daha çok kazandırır'], 'Çeşitlendirme, tek bir şirketteki kötü performansın etkisini azaltır; bu yüzden fonlar tek hisseye göre genellikle daha az riskli bulunur.'),
  ('Bir hanenin finansal sağlığı değerlendirilirken hangi ölçüt kısa vadeli dayanıklılığı en doğrudan gösterir?', 'Borçsuz gider karşılama gücü', ['Sahip olunan kredi kartı sayısı', 'Evdeki televizyon sayısı', 'Hesap numarasının uzunluğu'], 'Beklenmedik giderlere borç almadan dayanabilme gücü, finansal dayanıklılığın temel göstergelerinden biridir.'),
  ('Aynı banka içinde yapılan havale ile farklı bankaya gönderilen EFT\'yi karşılaştırırken aşağıdakilerden hangisi doğrudur?', 'Havale aynı banka, EFT farklı bankalar arasıdır', ['EFT yalnızca aynı bankada yapılır; havale yalnızca yurt dışına', 'İkisi de yalnızca nakit ödeme yöntemidir', 'İkisi de yalnızca kredi kartından yapılır'], 'Havale aynı bankadaki hesaplar, EFT farklı bankalardaki hesaplar arası transferdir; FAST ise anlık ve 7/24 çalışan EFT benzeri yöntemdir.'),
  ('Kredi kullandırılırken faizin yanı sıra banka ve sigorta muameleleri vergisi gibi vergilerin maliyete eklenmesi tüketici açısından neyi gerektirir?', 'Toplam geri ödemeyi kıyaslama', ['Vergilerin hiç hesaba katılmamasını', 'Kredi alınmamasını', 'Yalnızca peşin ödeme yapılmasını'], 'Vergi ve masraflar kredinin gerçek maliyetini artırır; farklı bankaları kıyaslarken toplam maliyet ya da yıllık maliyet oranına bakılmalıdır.'),
  ('500 gramlık paket 40 liraya, 1,2 kilogramlık paket 90 liraya satılıyor. Birim fiyat açısından hangisi daha ucuzdur?', '1,2 kg; kilosu 75 lira', ['500 g paket; kilosu 75 lira', '500 g paket; kilosu 80 lira', 'İkisi de kilosu 80 liradır'], '500 g paketin kilosu 80 lira, 1,2 kg paketin kilosu 90 ÷ 1,2 = 75 liradır. Birim fiyat doğru karşılaştırmayı sağlar.'),
  ('Peşin fiyatı vadeli fiyattan düşük olan bir mağazada peşin ödeme imkânı olan tüketici hangi koşulda peşin ödemeyi seçmelidir?', 'Alternatif getiri örtük faizden düşükse', ['Her zaman taksitli ödemeyi seçmelidir', 'Banka faizi ne olursa olsun peşin ödemelidir', 'Fiyat farkı hiçbir önem taşımadığında'], 'Peşin ödeme, vadeli fiyattaki gizli faizden kaçınmaktır. Paranın alternatif getirisi bu örtük faizden düşükse peşin ödemek avantajlıdır.'),
  ('Garanti süresi sonrasında "2 yıllık uzatılmış garanti" 800 liraya satılan bir cihazın arıza olasılığı yüzde 10, onarım maliyeti 3.000 liradır. Beklenen onarım maliyeti ile uzatılmış garantinin değerlendirmesi hangisidir?', 'Beklenen maliyet 300 lira; garanti kârsızdır', ['Beklenen maliyet 3.000 lira; garanti kârlıdır', 'Beklenen maliyet 800 lira; garanti adildir', 'Beklenen maliyet 100 lira; garanti çok ucuzdur'], '0,10 × 3.000 = 300 lira beklenen giderdir. 800 liralık garanti, ortalama olarak 300 lira için ödenen yüksek bir bedeldir.'),
  ('Finansal kiralamada (leasing) kullanıcı ile kiralayan arasındaki ilişkiyi en iyi hangisi açıklar?', 'Kullanır ve sonunda satın alma hakkı elde eder', ['Kiralayan, varlığı kullanıcıya hiç devretmez ve kira almaz', 'Kullanıcı bedeli peşin öder ve kiralayanı sözleşmeden çıkarır', 'Kiralayan yalnızca faiz geliri elde eden bir bankadır'], 'Leasing\'de kullanıcı kira bedeli öder; vade sonunda genellikle düşük bir bedelle mülkiyeti edinme seçeneği bulunur.'),
  ('Haftada bir kez kullanılan matkap için tüm komşuların ortak bir matkap kullanması ya da kiralama yapması ekonomik açıdan neden mantıklıdır?', 'Kişi başına maliyet yayılır', ['Matkap fiyatı her zaman sıfırdır', 'Kiralama her zaman satın almadan pahalıdır', 'Sık kullanılmayan ürünler değer kazanır'], 'Seyrek kullanılan aletlerde satın alma bedeli, kullanım başına yüksek maliyete dönüşür; paylaşım ya da kiralama toplam gideri azaltır.'),
  ('İkinci el bir otomobilin yeni araca göre ilk yıllardaki değer kaybı bakımından avantajı nedir?', 'Keskin düşüş önceki sahipte kalır', ['İkinci el araçlar hiç değer kaybetmez', 'Yeni araçların değer kaybı olmaz', 'İkinci el araçlar sigortalanamaz'], 'Araçlar ilk yıllarda hızlı değer kaybeder. İkinci el alan kişi bu keskin düşüşü büyük oranda başkasına bırakmış olur.'),
  ('Bir mağaza "100 liralık alışverişe 20 lira indirim kuponu, ancak kupon sonraki alışverişte geçerli" kampanyası yapıyor. Tüketici bu kampanyayı değerlendirirken hangi noktaya dikkat etmelidir?', 'Ek harcamaya yol açıp açmadığına', ['Kuponun rengine', 'Mağazanın logosunun büyüklüğüne', 'Kampanyanın duyuruldüğü saat dilimine'], 'Sonraki alışverişe bağlı kuponlar tüketiciyi ihtiyaç dışı harcamaya yöneltebilir. İndirim ancak zaten planlanmış harcamada gerçek tasarruftur.'),
  ('Bir kişi evde yemek yapmak yerine her gün dışarıdan 250 liralık yemek sipariş ediyor; evde yemeğin gıda maliyeti 80 liradır ve 1 saat hazırlık gerektirir. Saati 100 liraya değerlendirebilen biri için hangi seçenek ekonomik olarak daha avantajlıdır?', 'Evde yapmak; 180 liraya gelir', ['Sipariş vermek; maliyeti 80 liradır', 'Eşit; çünkü ikisi de 250 liradır', 'Hiçbir karşılaştırma yapılamaz'], 'Evde yemek 80 lira gıda artı 100 lira zaman maliyeti ile 180 liraya gelir. Sipariş 250 lira olduğundan evde yapmak ucuzdur.'),
  ('Yıl sonu indirimlerinde mevsim dışı kıyafetleri indirimde alıp bir sonraki yıl giymeyi planlayan tüketici hangi gelişmeyi hesaba katmalıdır?', 'Depolama ve moda riski', ['Faiz oranlarının sıfırlanması', 'Yalnızca ürünün barkod numarası', 'Kapı numarası'], 'İndirimli alımın avantajı, ürünün gerçekten kullanılma olasılığına bağlıdır; moda ve beden değişimi riski tasarrufu eritebilir.'),
  ('Lise mezununun yıllık geliri 240.000, üniversite mezununun 360.000 liradır. Dört yıllık özel üniversite için toplam ücret 400.000 lira ve okurken kaybedilen gelir 4 × 240.000 = 960.000 liradır. İskonto yapmadan geri ödeme süresi yaklaşık kaç yıldır?', '11,3 yıl', ['3,3 yıl', '8,0 yıl', '13,6 yıldır'], 'Toplam maliyet 1.360.000 liradır; ek yıllık gelir 120.000 lira olduğundan geri dönüş süresi yaklaşık 1.360.000 ÷ 120.000 = 11,3 yıldır.'),
  ('Teknolojinin hızla değiştiği bir sektörde çalışan kişi, becerilerini yenilemezse hangi riskle karşılaşır?', 'Beşeri sermayenin değer kaybı', ['Tüm mevduatının otomatik artması', 'Vergi borcunun silinmesi', 'Kredi kartı limitinin yükselmesi'], 'Bilgi ve beceriler zamanla eskir; sürekli öğrenme beşeri sermayeyi taze tutar ve gelir güvencesi sağlar.'),
  ('Mezun olduktan sonra eğitim kredisi borcu olan genç bir çalışan ilk maaşlarını nasıl planlamalıdır?', 'Taksiti sabit gider sayıp fon kurmalıdır', ['Taksiti hiç ödemeyip tüm parayı harcamalıdır', 'Yeni krediler çekip eskiyi ertelemelidir', 'Birikim yapmayı tamamen bırakmalıdır'], 'Borç yükümlülüğü bütçede sabit gider olmalı; ancak beklenmedik durumlar için acil durum fonu da oluşturulmalıdır.'),
  ('Yaşam döngüsü yaklaşımına göre bir kişinin ilk iş yıllarında beklenen finansal durum hangisidir?', 'Düşük gelir, yüksek ihtiyaç', ['Gelir en yüksek, harcama en düşüktür', 'Gelir ve harcama sıfırdır', 'Tüm borçlar kapanmıştır'], 'Gençlikte gelir düşük ve eğitim, taşınma gibi yatırım harcamaları yüksektir. Orta yaşta gelir artar ve birikim başlar.'),
  ('Çocuk sahibi olmayı planlayan bir çift için finansal planlamada hangi kalemin önceden bütçeye eklenmesi gerekir?', 'Bakım ve eğitim giderleri', ['Yalnızca bir kerelik hediye alımı', 'Emlak vergisi iadesi', 'Mevduat sigortası primi'], 'Çocukla birlikte bütçeye uzun dönemli yeni giderler girer; bu giderleri önceden planlamak mali baskıyı azaltır.'),
  ('Emekliliğe 10 yıl kalmış biri için birikim stratejisinde genel olarak hangi değişiklik beklenir?', 'Riskli varlık payını azaltmak', ['Tüm birikimi tek bir hisseye yatırmak', 'Yeni krediler çekmek', 'Birikim yapmayı bırakmak'], 'Yaklaşan emeklilikte kayıp yaşama ve toparlanma zamanı azaldığı için risk azaltılır; öngörülebilir araçlar ağırlık kazanır.'),
  ('Kısa vadeli (1 yıl içinde) bir tatil hedefi ile uzun vadeli (30 yıl sonra) bir emeklilik hedefi için araç seçiminde genel yaklaşım nasıl farklılaşır?', 'Kısa hedefte likit, uzun hedefte büyüme araçları', ['İki hedef için de aynı araçlar kullanılmalıdır', 'Kısa hedefte yüksek riskli araçlar, uzun hedefte yalnızca nakit', 'İki hedefte de yalnızca kredi kullanılmalıdır'], 'Zaman ufku uzadıkça kısa vadeli dalgalanma tolere edilebilir; kısa hedefte ise anaparanın korunması öncelik taşır.'),
  ('Aylık net geliri 45.000 lira olan bir kişi sıfır tabanlı bütçede zorunlu giderlere 27.000, isteğe bağlı harcamalara 9.000, borç ödemesine 6.000 lira ayırmıştır. Geriye atanmamış kalan tutar için doğru uygulama hangisidir?', '3.000 lirayı birikime atamak', ['3.000 lirayı atanmamış bırakmak', '3.000 lirayı bütçeden saklamak', '3.000 lirayı gelecek ayın giderine saymak'], 'Kalan 45.000 − 42.000 = 3.000 lira, sıfır tabanlı yöntemin gereği bir kalemle eşleştirilir; örneğin birikime ayrılır.'),
  ('Geliri aydan aya çok değişen bir kişi için dalgalı gelirli bütçelemede genellikle hangi yöntem önerilir?', 'En düşük gelire göre bütçe kurmak', ['Bütçeyi en yüksek aylık gelire göre kurmak', 'Giderleri gelire göre her gün değiştirmek', 'Hiç bütçe yapmamak'], 'En düşük gelire göre planlanan gider, kötü aylarda açık oluşmasını önler; fazla gelir fon olarak sonraki aylara aktarılır.'),
  ('Brüt aylık geliri 80.000 lira olan bir kişi için sık anılan 28/36 kuralına göre konutla ilgili toplam aylık giderin en fazla kaç lira olması önerilir?', '22.400 lira', ['28.800 lira', '36.000,00 lira', '29.000 lira'], '28/36 kuralında konut giderleri brüt gelirin en çok yüzde 28\'i olmalıdır: 80.000 × 0,28 = 22.400 lira. Toplam borç ödemeleri ise yüzde 36\'yı geçmemelidir.'),
  ('Aynı kişinin 28/36 kuralına göre bütün borç ödemeleri (konut dahil) için en yüksek aylık tutar kaç liradır?', '28.800 lira', ['22.400 lira', '36.000,00 lira', '80.000 lira'], 'Toplam borç ödemeleri brüt gelirin yüzde 36\'sı olmalıdır: 80.000 × 0,36 = 28.800 liradır.'),
  ('Borç servis oranı yüzde 50\'yi aşan bir hanenin yeni kredi başvurusunda bankanın tutumu için hangisi olasıdır?', 'Ödeme gücü sınırlı görülüp başvuru reddedilebilir', ['Başvuru otomatik olarak daha düşük faizle onaylanır', 'Banka borcun tamamını siler', 'Banka yalnızca vade uzatır'], 'Gelirin yarıdan fazlasının borca gitmesi, beklenmedik durumlara karşı esnekliği azaltır; bankalar bunu risk olarak değerlendirir.'),
  ('Kredi başvurusunda bankanın "kapasite" (ödeme gücü) ölçütüyle neyi değerlendirdiği hangisidir?', 'Taksitleri karşılama gücünü', ['Başvuranın adının kaç harfli olduğunu', 'Başvurunun yapıldığı günü', 'Şubenin büyüklüğünü'], 'Kapasite ölçütü gelir, mevcut borç ve gider dengesine bakarak yeni taksidin ödenebilirliğini tartar.'),
  ('Maaşını bankasından alan müşteriye bankanın daha düşük faizli teklif sunabilmesinin nedeni nedir?', 'Gelir düzenlidir', ['Banka maaşın yarısına el koyar', 'Maaşlı müşteri vergi ödemez', 'Maaşın vadesi uzundur'], 'Düzenli ve kayıtlı gelir, geri ödeme kapasitesinin göstergesidir; bu da bankanın risk primini düşürebilir.'),
  ('Gelir belgesi sunamayan ama teminat olarak tapulu bir ev gösteren biri için bankanın temel yaklaşımı hangisidir?', 'Teminat olsa da ödeme gücü sorgulanır', ['Teminat olduğu için gelir hiç sorgulanmaz', 'Kredi her zaman faizsiz verilir', 'Teminat varlığı kredi notunu en yükseğe çıkarır'], 'Teminat, ödenmeyen kredide alacağı güvenceye alır ama bankalar yine de borçlunun taksit ödeme gücünü incelemek zorundadır.'),
  ('Aylık geliri 40.000 lira olan bir kişi 1.200.000 liralık bir kredi için 120 ay vadeli, aylık taksiti 20.000 lira olan teklif alıyor. Taksidin gelire oranı yüzde kaçtır ve bu durum nasıl yorumlanır?', 'Yüzde 50; yüksek bir oran', ['Yüzde 5; çok düşük ve güvenli', 'Yüzde 20; ideal sınır', 'Yüzde 200; imkânsız'], '20.000 ÷ 40.000 = yüzde 50\'dir. Gelirin yarısının tek takside gitmesi bütçeyi sıkıştırır ve ek borç riskini artırır.'),
  ('Bir hanenin gelir, gider ve borç ödemelerini aylık bir çizelgede izleyip her ay gerçekleşenle planlananı karşılaştırması hangi uygulamadır?', 'Bütçe izleme', ['Likidite tuzağı', 'Stopaj hesabı', 'Yeniden iskonto'], 'Plan ve gerçekleşen karşılaştırıldığında hangi kalemlerin aşıldığı bulunur; bu bilgi ertesi ay bütçesini düzeltmek için kullanılır.'),
  ('Bir aile bütçesinde kira, elektrik, su ve internet faturası toplamının gelirin yüzde 45\'ini aştığı görülüyor. Daha esnek ve küçülebilir bütçe kalemi hangisidir?', 'İsteğe bağlı harcamalar', ['Kira sözleşmesinin sabit kira bedeli', 'Zorunlu sigorta primi', 'Elektrik abonelik bedeli'], 'Sabit giderler kısa vadede azaltılamaz; isteğe bağlı harcamalar ise bilinçli karar ve disiplinle kısılabilir.'),
  ('Hammurabi Kanunları\'nda tahıl borçlarına uygulanan faizin yaklaşık üçte bir, gümüş borçlarına ise yüzde 20 olarak belirlenmesi hangi gerçeği gösterir?', 'Faizin eski dönemlerde düzenlendiğini', ['Faizin yalnızca modern bankalarla ortaya çıktığını', 'Gümüşün hiç faiz getirmediğini', 'Borçların hiç yasal olmadığını'], 'MÖ 18. yüzyıldaki Hammurabi Kanunları, borç ve faiz oranlarına sınır koyarak faiz ilişkilerinin binlerce yıllık olduğunu gösterir.'),
  ('Bir kredinin faiz oranını reel faiz, beklenen enflasyon ve risk priminin toplamı olarak ele alan bir bakış açısına göre borçlunun riski arttığında faiz nasıl değişir?', 'Risk primi artar', ['Risk primi sıfırlanır ve faiz düşer', 'Enflasyon beklentisi azalır', 'Faiz hiçbir koşulda değişmez'], 'Riskli borçludan alacaklı daha yüksek getiri ister; bu yüzden aynı koşullarda risk primi ve toplam faiz yükselir.'),
  ('Aynı bankadan aynı vade için kredi çekmek isteyen iki kişiden güvenilir geçmişi olana daha düşük, kötü ödeme geçmişi olana daha yüksek faiz teklif edilmesinin nedeni nedir?', 'Temerrüt riskinin farklı olması', ['Bankanın kişisel zevkleri', 'Faizin ülkeden ülkeye aynı olması', 'Kredinin rengi'], 'Faiz oranı risk primi içerir; geri ödeme olasılığı düşük görünen borçludan daha yüksek faiz istenir.'),
  ('"Şimdi al, sonra öde" hizmetlerinin tüketici açısından en önemli riski aşağıdakilerden hangisidir?', 'Küçük taksitler birikip borç yükü olur', ['Ürünlerin vergiden tamamen muaf olması', 'Hizmetin her koşulda faizsiz ve ücretsiz olması', 'Alışverişlerin kayıt dışı kalması'], 'Ödeme acısını erteleyen bu hizmetler harcamayı artırabilir ve çok sayıda küçük taksit toplamda büyük bir yük oluşturabilir.'),
  ('Çevrim içi pazar yerlerinde ödemenin satıcıya ürün teslim edilip alıcı onayladıktan sonra aktarılması uygulaması hangi tür güvenceye örnektir?', 'Emanet ödeme', ['Zorunlu karşılık', 'Reeskont', 'Stopaj'], 'Emanet ödemede bedel aracı platformda bekler; ürün teslim edilene kadar satıcıya geçmez, böylece dolandırıcılık riski azalır.'),
  ('Kart bilgilerinin çevrim içi sitelerde gerçek numara yerine rastgele bir "jeton"la (token) saklanması hangi riski azaltır?', 'Veri hırsızlığı', ['Faiz maliyeti', 'Enflasyon etkisi', 'Gelir vergisi yükü'], 'Tokenizasyonda gerçek kart numarası yerine yalnızca anlamsız bir jeton saklanır; veri sızıntısında kart bilgisi korunmuş olur.'),
  ('Mobil cüzdan uygulamasında "otomatik tekrarlayan ödeme" ayarı açık olan bir kullanıcı için en önemli kontrol hangisidir?', 'Gereksiz ücretleri bulmak', ['Cüzdanın rengini değiştirmek', 'Telefonu her ay yenilemek', 'Vergi numarasını silmek'], 'Tekrarlayan ödemeler kullanılmayan hizmetlerde sessiz harcamaya yol açar; düzenli denetim gereksiz giderleri keser.'),
  ('Temassız kartla düşük tutarlı ödemelerde şifre sorulmaması hangi dengeyi gözetir?', 'Hız ve güvenlik dengesi', ['Banka kârının sıfırlanması', 'Kredi notunun yükselmesi', 'Vergi oranının düşmesi'], 'Küçük tutarlarda şifre aranmaması işlemi hızlandırır; yetkisiz kullanımı sınırlandırmak için işlem tutarı ve adedi sınırlıdır.'),
  ('Bir uygulama "ilk ay ücretsiz, sonrasında kartından aylık ücret çekilecek" şartıyla deneme sunuyor. Tüketicinin yapması gereken en uygun şey nedir?', 'İptal tarihini takip etmek', ['Kart bilgilerini hiç silmemek', 'Her ay ücretin çekilmesine alışmak', 'Faturayı yok saymak'], 'Ücretsiz deneme sonrası otomatik ücretlendirme yaygındır; iptal tarihi takip edilmezse istenmeyen abonelik başlar.'),
  ('Çevrim içi alışverişte kart bilgisini girmeden "Havale/EFT ile ödeme" seçmek hangi durumda daha riskli olabilir?', 'Satıcı tanınmıyorsa para geri alınmaz', ['Kartla ödemeden her zaman daha güvenlidir', 'Faiz getirdiği için', 'İşlem vergiden muaf olduğu için'], 'Kartla ödemede itiraz (chargeback) hakkı varken havalede para satıcıya doğrudan geçer; dolandırıcı satıcıda geri alma zordur.'),
  ('Biletin 50 lira olduğu, 100.000 bilet satılan bir çekilişte 1 adet 1.000.000 lira, 10 adet 10.000 lira ve 100 adet 500 liralık ikramiye vardır. Bir biletin beklenen ödülü kaç liradır?', '11,5 lira', ['150,0 lira', '25,0 lira', '1,15 lira'], 'Toplam ikramiye 1.000.000 + 100.000 + 50.000 = 1.150.000 liradır; bilet başına 1.150.000 ÷ 100.000 = 11,5 lira. Bilet fiyatı beklenen ödülün çok üzerindedir.'),
  ('Beklenen ödülü bilet fiyatından düşük olan şans oyunlarını sürekli oynayan bir kişi uzun vadede ne bekleyebilir?', 'Ortalama olarak yatırdığından az geri almayı', ['Ortalama olarak yatırdığının iki katını almayı', 'Kesin olarak her oyunda kazanmayı', 'Oyun sayısı arttıkça beklenen kaybın sıfırlanmasını'], 'Beklenen değer negatifse oyun sayısı arttıkça gerçekleşen sonuç beklenen kayba yaklaşır; şans oyunları düzenleyenin avantajı yüksektir.'),
  ('Kaybettiği parayı "bir sonraki oyunda geri kazanırım" diyerek bahisleri artıran kişinin davranışı ekonomik olarak hangi önemli hatayı içerir?', 'Beklenen kaybı büyütmek', ['Faiz gelirini artırmak', 'Vergi avantajı sağlamak', 'Fırsat maliyetini sıfırlamak'], 'Her oyunun beklenen değeri aynıysa kayıp telafi etmek mümkün değildir; yüksek bahis beklenen kaybı büyütür.'),
  ('Mevduat faizi, stopaj ve enflasyon dikkate alındığında bir birikimin gerçek değerini korumak için gereken asgari net getiri neye eşit olmalıdır?', 'Enflasyona', ['Yasal faiz oranına', 'Sıfıra', 'Kredi faizine'], 'Net nominal getiri enflasyona eşitse reel getiri sıfırdır ve satın alma gücü korunur; fazlası gerçek kazançtır.'),
  ('Standart formlarla hazırlanmış bir hizmet sözleşmesinde "ürünü hiçbir koşulda iade edemezsiniz" maddesi bulunuyor. Bu madde tüketici hukuku açısından nasıl değerlendirilir?', 'Haksız şart sayılır', ['İmzalandığı için her koşulda geçerlidir', 'Yalnızca satıcıyı bağlar', 'Tüketiciye ek hak tanır'], 'Kanunun tanıdığı cayma ve ayıp haklarını kaldıran standart şartlar tüketici aleyhine dengesizlik yaratır ve geçersizdir.'),
  ('Borcunu daha düşük faizli yeni bir krediyle kapatmayı düşünen kişi, vade sonuna kadar kalmayı planlamıyorsa karar verirken özellikle hangi hesabı yapmalıdır?', 'Masrafın geri dönüş süresi', ['Eski bankanın şube sayısı', 'Bankanın logosunun yaşı', 'Yalnızca taksit sayısının tek rakam olması'], 'Refinansmanda masraf ve tasarruf karşılaştırılır; kalma süresi geri dönüş süresinden kısaysa yeni kredi zarar yazdırabilir.'),
  ('Borçlu bir kişi "taksit erteleme" (ödeme tatili) kullanırsa ertelenen dönemde faiz işleyişi için genel durum nedir?', 'Faiz işlemeye devam edebilir', ['Faiz sıfırlanır', 'Borç silinir', 'Taksit sayısı otomatik olarak düşer'], 'Erteleme, ödemeyi öteler; ancak sözleşmeye göre faiz çoğunlukla işlemeye devam eder ve toplam maliyet büyür.'),
  ('Değişken faizli kredisi olan bir kişi referans faiz yükselince bankasından taksit tutarının arttığı bilgisini alıyor. Bu durumda neden bütçe planlaması daha zordur?', 'Taksit tutarı öngörülemez', ['Taksit asla değişmediği için', 'Faiz yalnızca vergi nedeniyle değiştiği için', 'Bankanın sabit komisyonu arttığı için'], 'Değişken faizde taksit referans orana göre güncellendiği için borçlu gelecekteki ödeme tutarından emin olamaz.'),
  ('Konut kredisinde kalan vadenin kısa tutulması (örneğin 10 yıl yerine 5 yıl) için hangisi doğrudur?', 'Taksit artar, toplam faiz azalır', ['Taksit düşer ve toplam faiz de artar', 'Taksit ve toplam faiz aynı kalır', 'Kredi hiç ödenmez'], 'Kısa vadede borç hızla erir; aylık yük artar ama faizin işlediği süre kısaldığı için toplam faiz azalır.'),
  ('İhtiyaç kredisiyle tatil planı yapan bir kişi için en akılcı değerlendirme hangisidir?', 'Faydayı borç maliyetiyle kıyaslamak', ['Tatil bedelini asla düşünmemek', 'Faizi hiç hesaplamamak', 'Daha fazla kredi çekip tatili uzatmak'], 'Borçla finanse edilen tüketimde fayda anlıktır ama faiz maliyeti kalıcıdır; bu yüzden toplam maliyetin faydaya değip değmediğine bakılmalıdır.'),
  ('Gelirini üç aydır kaybetmiş bir borçlunun taksit ödemekte zorlanacağını fark etmesi halinde en doğru ilk adım hangisidir?', 'Bankayla görüşüp yapılandırma sormak', ['Hiç haber vermeden ödemeleri bırakmak', 'Başka bankadan nakit avans çekmek', 'Bankanın telefonlarını açmamak'], 'Erken görüşme, gecikme faizi ve kayıt riskini azaltır; bankalar çoğunlukla yapılandırma seçenekleri sunar.'),
  ('Konut kredisi ile ev alan bir kişinin, evi sattığında kredi bakiyesini kapatması gereken durumda tapudaki hangi kaydın kaldırılması gerekir?', 'İpotek kaydı', ['Vergi levhası', 'Rehin şerhinin yenilenmesi', 'Gelir beyanı'], 'İpotek, kredi borcu kapatılınca tapudan fekki (kaldırılma) işlemiyle silinir; böylece konut yeni alıcıya ipoteksiz devredilebilir.'),
  ('Kredi kartı ve ihtiyaç kredisi faizleri karşılaştırıldığında kart nakit avansının aylık faizi genellikle yüksek olduğundan, 6 ay içinde ödenecek 20.000 liralık acil gider için en makul yol nedir?', 'En düşük toplam maliyetli seçeneği seçmek', ['Kartın nakit avansını otomatik tercih etmek', 'Aynı gün üç banka kartıyla avans çekmek', 'Faiz oranına bakmadan en hızlı yolu seçmek'], 'Kredi türleri arasında faiz oranı ve masraf farklıdır; toplam maliyeti kıyaslamak gereksiz faiz ödemeyi önler.'),
  ('Aynı anapara, oran ve gün sayısında yılın 360 gün yerine 365 gün alınması faiz tutarını nasıl etkiler?', 'Faiz tutarı biraz azalır', ['Faiz tutarı biraz artar', 'Faiz tutarı değişmez', 'Faiz tutarı iki katına çıkar'], 'Faiz günlük orana bölünerek hesaplanır; yıl uzadıkça günlük oran küçülür ve aynı gün sayısı için faiz azalır.'),
  ('Bir bankanın "yıllık yüzde 24 faiz, günlük bileşik" ilanı için aşağıdakilerden hangisi doğrudur?', 'Efektif yıllık getiri yüzde 24\'ten yüksektir', ['Efektif yıllık getiri yüzde 24\'ten düşüktür', 'Efektif yıllık getiri tam olarak yüzde 24\'tür', 'Getiri günlük sayısına bağlı olarak sıfırlanır'], 'Aynı nominal oranda bileşikleme sıklığı artınca efektif getiri yükselir; günlük bileşikte efektif oran yaklaşık yüzde 27,1 olur.'),
  ('Aynı kartta asgari ödeme yapılıp 16.000 lira devrettiğinde aylık yüzde 4 faiz işlerse bir sonraki dönemin faiz tutarı kaç liradır?', '640 lira', ['400 lira', '800 lira', '1.600 lira'], 'Devreden borç 16.000 lira, aylık faiz 16.000 × 0,04 = 640 liradır.'),
  ('Yalnızca asgari ödeme yapıp yeni harcama yapmayan bir kart sahibinin borcu sonraki dönemlerde nasıl değişir?', 'Borç yavaş azalır', ['Borç hemen sıfırlanır', 'Borç değişmez', 'Borç her ay iki kat artar'], 'Asgari ödeme anaparaya ve faize gider; kalan borç azalsa bile faiz yükü nedeniyle uzun süre kapanmayabilir.'),
  ('Bir bankanın toplam kredi kartı limitini üç karta bölmesi ve kullanıcının bunların hepsini doldurması durumunda kredi riski açısından ne söylenebilir?', 'Toplam kullanım oranı yüksek görünür', ['Kredi notu mutlaka artar', 'Banka kartları birleştirir ve borcu siler', 'Faiz oranı sıfırlanır'], 'Kredi notu değerlendirmesinde toplam limit kullanımı önemlidir; kartlar dolu olduğunda borçlu daha riskli algılanır.'),
  ('Birden fazla kredi kartı borcunu tek bir düşük faizli kredide toplayan kişi kart borçlarını kapatınca kartlarla yeniden harcama yaparsa en olası sonuç nedir?', 'Toplam borç yükü artar', ['Borç tamamen ortadan kalkar', 'Kredi notu otomatik olarak artar', 'Faiz oranı sıfırlanır'], 'Konsolidasyon yalnızca borcu yeniden düzenler; harcama alışkanlığı değişmezse yeni kart borcu eskisinin üzerine biner.'),
  ('Bir kişi, başkasının kredisine kefil olmadan önce ne yapmalıdır?', 'Borçlunun ödeme gücünü incelemelidir', ['Sözleşmeyi okumadan imzalamalıdır', 'Borçlunun adını duymadan karar vermelidir', 'Sadece güven duygusuna güvenmelidir'], 'Kefil, borçlunun ödeyememesi halinde kaybı üstlenir; bu risk, kefalete girmeden önce değerlendirilmelidir.'),
  ('Kredi kartıyla alışveriş sırasında verdiğiniz tutardan fazla çekim yapıldığını ekstrede fark ediyorsunuz. Hangi hakkınızı kullanabilirsiniz?', 'Bankaya itiraz etmek', ['İtiraz hakkınız yoktur', 'Tutarı ödeyip hiç şikâyet etmeme', 'Banka kartını hemen satma'], 'Hatalı ya da yetkisiz kart işlemlerinde itiraz hakkı vardır; süresinde yapılan itiraz üzerine banka inceleme yapar.'),
  ('Bir kişinin üç farklı bankadaki kartlarının ekstre tarihleri farklı günlere düşüyor ve kişi bazen ödeme gününü kaçırıyor. Bu durumu çözmek için en pratik çözüm hangisidir?', 'Otomatik ödeme talimatı vermek', ['Kartların tümünü hiç kapatmamak', 'Kartları başkasına devretmek', 'Ödeme tarihlerini rastgele seçmek'], 'Aynı döneme getirilmiş ödeme takvimi ve otomatik talimat kaçırılan ödeme riskini azaltır.'),
  ('Kredi kartından yapılan bir yurt dışı harcamasının ekstreye farklı bir kurdan yansımasının temel nedeni hangisidir?', 'Kur farkı ve marj', ['Faizin vergiden muaf olması', 'Kartın limitinin artması', 'Kartın rengi'], 'Yabancı para harcamalar işlem tarihinde değil, bankanın kurduğu günde kurla dönüştürülür; kur farkı ve komisyon eklenir.'),
  ('Kredi kartı limitini ihtiyaç duymadığı halde artıran bir tüketicinin başlıca riski nedir?', 'Borçlanma eğilimini artırır', ['Kredi notunun sıfıra inmesi', 'Kartın otomatik kapanması', 'Hesap işletim ücretinin silinmesi'], 'Daha yüksek limit, harcama sınırını yükseltir; kişi dürtüsel harcama eğilimindeyse borç riski büyür.'),
  ('Thaler ve Benartzi\'nin "Yarın Daha Fazla Biriktir" (Save More Tomorrow) programı çalışanlara hangi yöntemle birikimlerini artırtmıştır?', 'Zamların bir kısmını önceden birikime ayırma', ['Katılımcılara ek kredi vererek', 'Birikim hesaplarının faizini yarıya indirerek', 'Emeklilik hesaplarını kapatarak'], 'Program, çalışanların zam alınca bugünkü net maaşları düşmeden katkı oranını artırmasına dayanır; böylece kayıptan kaçınma ve ertelemeye yatkınlık aşılır.'),
  ('Yatırımcıların değer kazanmış varlıklarını erken satıp değer kaybetmiş varlıklarını elinde tutma eğilimine ne ad verilir?', 'Eğilim etkisi', ['Fisher etkisi', 'Likidite etkisi', 'Çarpan etkisi'], 'Shefrin ve Statman\'ın tanımladığı eğilim etkisi, kayıp gerçekleştirmenin acısından kaçınmak için kaybedenleri tutma davranışıdır.'),
  ('Kahneman ve Tversky\'ye göre kayıpların psikolojik etkisi aynı büyüklükteki kazançlara kıyasla yaklaşık ne kadardır?', 'İki kat', ['Yaklaşık yarısı', 'Aynı', 'Yaklaşık on kat'], 'Kayıptan kaçınma katsayısının deneylerde yaklaşık 2 ile 2,5 arasında çıktığı bildirilir; kayıplar kazançlardan daha ağır hissedilir.'),
  ('Birikim yaparken "tatil", "acil durum" ve "emeklilik" için ayrı hesaplar tutan kişinin davranışı hangi kavramın olumlu kullanımıdır?', 'Zihinsel muhasebe', ['Kayıt dışı ekonomi', 'Aşırı özgüven', 'Çerçeveleme etkisi'], 'Hedefe göre ayrılmış hesaplar harcamayı sınırlar ve birikimi korur; zihinsel muhasebe böylece disiplin aracına dönüşür.'),
  ('Emeklilik hesabından erken çekimde ceza uygulanması, kişinin ileride kendini kısıtlamasını sağlayan hangi araca örnektir?', 'Taahhüt aracı', ['Likidite tuzağı', 'Reeskont', 'Kredi derecelendirme'], 'Taahhüt araçları, kişinin bugünkü iradesini gelecekteki dürtüsel kararlara karşı korur; erken çekim cezası gibi.'),
  ('Çok sayıda benzer yatırım fonu arasında seçim yapamayıp hiçbirini seçmeyen kişi hangi eğilimi sergiler?', 'Karar felci', ['Likidite tercihi', 'Vergi indirimi', 'Fiyat tavanı'], 'Çok fazla seçenek karşılaştırmayı zorlaştırır; kişi kararı erteler ya da hiç vermez.'),
  ('Alışveriş yapılan mağazada ödeme sırasında "kartla ödeme" yerine "nakit" kullanmanın bazı insanlarda harcamayı azaltmasının nedeni nedir?', 'Nakdin daha çok acı vermesi', ['Nakdin faiz getirmesi', 'Nakdin vergiden muaf olması', 'Nakit için kredi notunun yükselmesi'], 'Nakit ödeme, harcamanın fiziksel olarak görülmesini sağlar; kartla ödemede harcama soyutlaşır ve ödemenin acısı azalır.'),
  ('Cep telefonu gibi birçok malda yasal asgari garanti süresi teslim tarihinden itibaren kaç yıldır?', '2 yıl', ['6 ay', '1 yıl', '5 yıldan fazla'], 'Garanti Belgesi Yönetmeliği\'ne göre garanti süresi, kural olarak teslim tarihinden itibaren iki yıldan az olamaz; konutta bu süre beş yıldır.'),
  ('Üretici ya da ithalatçının satış sonrası hizmet olarak yedek parça bulundurma yükümlülüğü genel olarak malın üretiminden ya da ithalatından sonra yaklaşık kaç yıl sürer?', '10 yıl', ['1 yıl', '3 yıl', '25 yıldan fazla'], 'Tüketici mevzuatında üreticinin, malın tüketicinin kullanımına sunulmasından sonra en az on yıl yedek parça ve servis sağlama yükümlülüğü vardır.'),
  ('Bir mağazanın reklamında "tüm ürünlerde yüzde 50 indirim" yazıp yalnızca birkaç ürüne indirim uygulaması tüketici hukuku bakımından hangi kavramla ilgilidir?', 'Aldatıcı reklam', ['Mevduat sigortası', 'Vade merdiveni', 'Reeskont'], 'Yanıltıcı bilgi vererek tüketiciyi karar vermeye yöneltmek haksız ticari uygulamadır; reklamlar Reklam Kurulu\'nun denetimindedir.'),
  ('Evinize gelen bir satıcıyla yaptığınız sözleşmeden (kapıdan satış) cayma hakkınız genel olarak kaç gündür?', '14 gün', ['2 iş günü', '30 gün', '60 gün'], 'İş yeri dışında kurulan sözleşmelerde tüketici, ürünü teslim aldığı günden itibaren 14 gün içinde gerekçe göstermeksizin cayabilir.'),
  ('Emeklilik birikimi yatırım araçlarında değerlendirilirken yatırımcının yaşı ilerledikçe hisse payını azaltması neden mantıklıdır?', 'Toparlanma süresi kısaldığı için', ['Yaşlılıkta enflasyonun sıfırlandığı için', 'Hisselerin yaşlılara satılamadığı için', 'Vergilerin yaşa göre arttığı için'], 'Uzun vadeli yatırımcı geçici düşüşleri bekleyebilir; emekliliğe yaklaşan kişinin toparlanma süresi azalır, bu yüzden riski düşürür.'),
  ('Kamu emeklilik aylığının yeterli olmadığı düşünülen bir çalışan için ek birikim planında ilk yapılması gereken hesap hangisidir?', 'Aradaki farkı belirlemek', ['Kredi kartı limitini hesaplamak', 'Sigorta primi iadesini hesaplamak', 'Faiz oranının sıfır olduğunu varsaymak'], 'Emeklilik planlaması, hedef geliri ve beklenen kamu aylığını karşılaştırarak kapatılması gereken açığı bulmakla başlar.'),
  ('Emeklilik fonlarında yönetim ücretinin düşük olması uzun vadede neden önemlidir?', 'Küçük fark bileşik etkiyle büyür', ['Ücret yalnızca bir kez ödenir ve etkisi olmaz', 'Ücretler vergiden düşülür ve fark yaratmaz', 'Ücret oranı getiriyi garanti eder'], 'Her yıl getirinin bir kısmı ücrete gittiği için bileşik büyüme yavaşlar; yıllarca süren farklar büyük tutarlara ulaşır.'),
  ('Resmî enflasyon yüzde 50 iken bir kişinin kişisel enflasyonunun yüzde 62 olması neyi gösterir?', 'Ağırlıklı kalemlerde artış daha hızlıdır', ['Resmî enflasyonun hatalı hesaplandığını kesin olarak', 'Kişinin gelirinin arttığını', 'Fiyatların düştüğünü'], 'Resmî endeks ortalama sepete göre hesaplanır; kişi sepeti farklıysa kişisel enflasyon bundan sapabilir.'),
  ('Yüzde 14 faizli sabit oranlı bir mevduat ve yüzde 20 yıllık enflasyon durumunda, aynı oranla sabit faizli bir krediyle borçlanan kişinin reel faiz maliyeti için ne söylenebilir?', 'Reel faiz negatif; borçlu lehine', ['Reel faiz pozitiftir; borçlu aleyhinedir', 'Reel faiz sıfırdır; kimse etkilenmez', 'Reel faiz yüzde 34\'tür'], 'Nominal faiz enflasyonun altında olduğundan reel faiz yaklaşık −yüzde 5\'tir; borcun reel değeri eriyerek borçluyu kollar.'),
  ('İkinci bir iş yaparak ek gelir elde eden bir çalışan, ek gelirinin bir bölümünün vergi nedeniyle daha yüksek oranla kesilmesini neden bekleyebilir?', 'Üst vergi dilimine girilebildiği için', ['Vergi oranının sabit olduğu için', 'Ek gelirin vergiden muaf olduğu için', 'Vergi dilimlerinin yıl ortasında kalktığı için'], 'Artan oranlı vergide toplam gelirin üst dilime geçen kısmı daha yüksek oranla vergilenir; ek gelirin net getirisi brüt tutardan düşük olur.'),
  ('Evi yangında hasar gören kişi, konut sigortası olmadığı için onarım parasını bulmak zorunda kalıyor. Kişisel risk yönetimi açısından bu olay neyi gösterir?', 'Sigortayla riski aktarmanın önemini', ['Riskin hiçbir zaman gerçekleşmeyeceğini', 'Sigortanın gereksiz olduğunu', 'Birikimin hiçbir işe yaramadığını'], 'Düşük olasılıklı ama yüksek maliyetli olaylar sigortayla karşılanmazsa birikimi eritebilir; sigorta bu riski sigortacıya aktarır.'),
  ('Yeni mezun bir çalışanın ilk maaşıyla birlikte aşağıdaki adımlardan hangisini ilk sırada atması en mantıklıdır?', 'Borçları görüp küçük bir acil fon başlatmak', ['Tüm maaşı lüks tüketime ayırmak', 'Hemen en büyük konut kredisini çekmek', 'Birikim yapmayı bırakıp kredi kartı limitini yükseltmek'], 'Borç ve zorunlu giderler netleşince küçük de olsa bir acil durum fonu kurmak, ilk finansal güvenlik adımıdır.'),
  ('Aylık 36.000 lira geliri olan bir öğrenci, ev arkadaşlarıyla kirayı paylaşarak kira giderini 12.000 liradan 8.000 liraya düşürüyor. Bu tasarruf yılda kaç liradır ve gelire oranı yaklaşık nedir?', '48.000 lira; yüzde 11', ['12.000 lira; yıllık gelirin yüzde 3\'ü', '96.000 lira; yıllık gelirin yüzde 22\'si', '4.000 lira; yıllık gelirin yüzde 1\'i'], 'Aylık tasarruf 4.000 lira, yıllık 48.000 liradır; yıllık gelir 432.000 olduğundan oran yaklaşık yüzde 11,1\'dir.'),
  ('Borçlu bir emeklinin aylık 30.000 lira geliri var ve 12.000 liralık borç taksidi ödüyor. Bu emekli için bütçenin en önemli sorunu nedir?', 'Kalan payın daralması', ['Gelirin tamamının birikime ayrılması', 'Borç taksidinin gelirden fazla olması', 'Gelirin sıfır olması'], '12.000 ÷ 30.000 = yüzde 40\'tır; sabit gelirle yaşayan kişi için borç yükü esnekliği azaltır.'),
  ('Yüksek enflasyon döneminde kira sözleşmesini her yıl yeniden yapmak yerine uzun süreli ve artış oranı bağlanmış bir sözleşme tercih eden kiracı neyi amaçlar?', 'Kira artışlarının öngörülebilir olması', ['Kiranın hiç ödenmemesini', 'Kira bedelinin sıfırlanmasını', 'Ev sahibinin sorumluluklarının kalkmasını'], 'Artış oranı baştan belirlenirse kiracı bütçesini ileriye dönük planlayabilir; yasal sınırlar içinde belirsizlik azalır.'),
  ('Fiyatı yüzde 25 artırılan bir ürünün yeniden eski fiyatına dönmesi için gereken indirim oranı kaçtır?', 'Yüzde 20', ['Yüzde 25', 'Yüzde 15', 'Yüzde 30\'a yakın'], 'Yeni fiyat 1,25 katıdır. Eski fiyata dönmek için 1 ÷ 1,25 = 0,80 gerekir; yani yüzde 20 indirim yeterlidir.'),
  ('Gelir yüzde 20 azalan bir hanenin gelirini eski düzeyine çıkarması için ek gelire ne kadar artış gerekir?', 'Yüzde 25', ['Yüzde 20', 'Yüzde 30', 'Yüzde 15\'e yakın'], 'Gelir 0,80 katına inmiştir; eskiye dönmek için 1 ÷ 0,80 = 1,25 katına çıkması, yani yüzde 25 artması gerekir.'),
  ('Anayasa\'ya göre yalnızca sözleşmeden doğan bir borcu ödeyememe nedeniyle kişi için hangisi doğrudur?', 'Özgürlüğünden alıkonulamaz', ['Hapis cezası zorunludur', 'Borç otomatik olarak silinir', 'Faiz yasaklanır'], 'Anayasa md. 38\'e göre hiç kimse yalnızca sözleşmeden doğan bir yükümlülüğü yerine getirememesinden dolayı özgürlüğünden alıkonulamaz; ancak mal varlığı haczedilebilir.'),
  ('İcra takibinde ödeme emri tebliğ edilen kişi borca itiraz etmek istiyorsa genel olarak kaç gün içinde itiraz etmelidir?', 'Yedi gün', ['Bir gün', 'Otuz gün', 'Doksan gün'], 'İcra ve İflas Kanunu\'na göre ödeme emrine itiraz süresi, tebliğden itibaren 7 gündür; süre geçerse takip kesinleşebilir.'),
  ('Borç ödemesini aksattığı için aleyhine icra takibi başlatılan ama haksız olduğunu düşünen kişi hangi hakkını süresi içinde kullanmazsa takip kesinleşir?', 'Ödeme emrine itiraz hakkını', ['Faiz hakkını', 'Vergi iadesi hakkını', 'Kredi limiti artırma hakkını'], 'İtiraz süresinde itiraz edilmezse borç kesinleşir ve haciz aşamasına geçilebilir; bu nedenle tebligatlar ciddiye alınmalıdır.'),
  ('Kişinin kendi kredi geçmişini ve kredi notunu öğrenebileceği ücretli ya da ücretsiz hizmetin sahibi Kredi Kayıt Bürosu hangi tür kuruluştur?', 'Bankaların kurduğu kuruluş', ['Bir ticaret odası ve borsa birliği', 'Bir sigorta ve emeklilik şirketi', 'Bir üniversite araştırma birimi'], 'Kredi Kayıt Bürosu (KKB), bankaların ortak kurduğu ve bireylerin kredi verilerini toplayıp raporlayan bir kuruluştur; Findeks hizmeti buna aittir.'),
  ('Peşin fiyatı 20.000 lira olan bir buzdolabının yıllık elektrik gideri 2.000 lira, enerji verimli modelin fiyatı 26.000 lira ve yıllık elektrik gideri 1.200 liradır. Fiyat farkının elektrik tasarrufuyla geri dönüş süresi kaç yıldır (iskontosuz)?', '7,5 yıl', ['3,0 yıl', '5,0 yıl', '10,0 yıl'], 'Ek maliyet 6.000 lira, yıllık tasarruf 800 liradır. 6.000 ÷ 800 = 7,5 yılda yatırım geri döner.'),
  ('"Altın günü" olarak bilinen düzende 12 kişi her ay 5.000 lira topluyor ve her ay sırayla bir kişiye tüm havuz veriliyor. Bir ay sonra parayı alan kişi ne kadar alır ve bu düzen ekonomik olarak neye benzer?', '60.000 lira; ilk alan faizsiz borçlanır', ['5.000 lira; herkes aynı tutarı alır', '60.000 lira; ilk alan faizli kredi almış gibidir', '12.000 lira; faizli mevduat gibidir'], '12 kişi × 5.000 = 60.000 liradır. İlk alan kişi sonraki aylarda katkı yapmaya devam edeceği için aslında faizsiz kredi kullanmış olur; sonda alan ise faizsiz kredi vermiş olur.'),
  ('Altın günü düzeninde sıra sonunda para alacak kişinin en önemli riski nedir?', 'Önce alanların ödemeyi bırakması', ['Faiz oranının sıfır olması', 'Paranın hiç ödenmemesi yasasının olması', 'Kişilerin sayısının artması'], 'Düzen güvene dayanır ve hukuki güvencesi yoktur; ilk çeken ödemeyi bırakırsa sonda alacak olanlar zarar eder.'),
  ('Muhammed Yunus ve Grameen Bank\'a 2006\'da Nobel Barış Ödülü verilmesinin temel nedeni hangisidir?', 'Yoksullara mikrokredi vererek kalkınmaya katkı', ['Büyük şirketlere düşük faizli kredi sağlamaları', 'Merkez bankası politikasını yönetmeleri', 'Altın rezervlerini artırmaları'], 'Grameen Bank, teminat arayan bankaların dışladığı yoksul kişilere, özellikle kadınlara küçük krediler vererek mikrofinansı yaygınlaştırdı.'),
  ('Evlilikte yasal mal rejimine göre evlilik sırasında çalışarak edinilen birikimler boşanma halinde nasıl işlem görür?', 'Katılma alacağıyla paylaşılır', ['Tamamı yalnızca kazanan eşe kalır', 'Tamamı devlete geçer', 'Çocuklara bölüştürülür'], 'Evlilik süresince çalışma karşılığı edinilen mallar edinilmiş mal sayılır; tasfiyede her eş diğerinin edinilmiş mallarının yarısı üzerinde katılma alacağına sahiptir.'),
  ('İşverenin çalışanlara sunduğu yemek kartı, özel sağlık sigortası ve ulaşım desteği gibi yan hakların toplam paket değerlendirmesinde hangi yaklaşım doğrudur?', 'Yan haklar da toplama eklenir', ['Yalnızca brüt maaşa bakılmalıdır', 'Yan haklar önemsizdir', 'Yan haklar hiç vergilendirilmez ve sayılmaz'], 'İş tekliflerini karşılaştırırken nakit maaş, yan haklar ve vergi etkileri birlikte değerlendirilmelidir.'),
  ('Konut kira geliri elde eden bir ev sahibi, kira geliri yıllık istisna tutarının altında kalıyorsa vergi bakımından ne durumdadır?', 'Beyan etmek zorunda kalmaz', ['Daima yüzde 50 vergi öder', 'Gelirini hiç kaydedemez', 'Vergi levhası alma zorunluluğu doğar'], 'Konut kira gelirlerinde her yıl güncellenen bir istisna tutarı vardır; gelir bu tutarı aşmazsa vergilendirme yapılmaz.'),
  ('Aylık maaşı yanında ek olarak ikramiye alan bir çalışan ikramiyenin vergi sonrası tutarını nasıl bilebilir?', 'İkramiye de kesintiye tabidir', ['İkramiye vergisizdir ve kesintisizdir', 'İkramiye yalnızca KDV\'ye tabidir', 'İkramiye hiçbir hesapta görünmez'], 'İkramiye, ücretin parçası olduğundan gelir vergisi, SGK ve damga vergisi kesintilerine tabidir; net tutar brüt tutardan düşüktür.'),
  ('İki iş teklifinden biri aylık 50.000 lira, diğeri aylık 45.000 lira artı ilk yıl 100.000 lira işe giriş primi sunuyor. İlk yıl toplam kazanç bakımından hangisi öndedir?', 'İkinci teklif; yıllık toplam 640.000 lira', ['Birinci teklif; yıllık toplam 600.000 lira', 'İki teklif eşittir', 'Birinci teklif; yıllık toplam 660.000 lira'], 'İkinci teklifte 45.000 × 12 + 100.000 = 640.000, birinci teklifte 600.000 liradır. Ancak ikinci yıldan sonra maaşı daha düşük olduğundan uzun vadede karşılaştırma değişir.'),
  ('Aylık yüzde 3 faizle kredi çeken ve parayı aylık yüzde 2 getirili bir araca yatıran kişinin aylık net sonucu için ne söylenebilir?', 'Her ay faiz farkı kadar zarar eder', ['Her ay faiz farkı kadar kazanır', 'Net sonuç sıfırdır', 'Faiz farkı yalnızca vergi ödemesine bağlıdır'], 'Borç maliyeti getiriden yüksek olduğunda negatif getiri farkı oluşur; borçla birikim yapmak bu durumda zarara yol açar.'),
  ('Maaş promosyonu için bir bankayla üç yıllık maaş anlaşması yapan çalışan, ileride daha avantajlı bir banka çıkarsa neyi göze almış demektir?', 'Geri ödeme ve esneklik kaybı', ['Maaşın tamamen artmasını', 'Vergi muafiyetini', 'Banka kartının ücretsiz yenilenmesini'], 'Promosyon taahhüde bağlı olduğundan erken ayrılmada geri ödeme doğabilir; toplam fayda esneklikle birlikte değerlendirilmelidir.'),
  ('Varlıkları paraya çevrilebilirlik (likidite) açısından en yüksekten en düşüğe doğru sıralayan seçenek hangisidir?', 'Nakit, vadesiz mevduat, yatırım fonu, gayrimenkul', ['Gayrimenkul, yatırım fonu, vadesiz mevduat, nakit', 'Yatırım fonu, nakit, gayrimenkul, vadesiz mevduat hesabı', 'Vadesiz mevduat, gayrimenkul, nakit, yatırım fonu'], 'Nakit ve vadesiz hesap anında kullanılır; fon birkaç iş günü, gayrimenkul ise haftalar ya da aylar süren işlemle paraya çevrilir.'),
  ('Hesabında yeterli bakiye bulunmayan kişi kredili mevduat (ek) hesabını kullandığında bankaya ne ödeyecektir?', 'Kullanılan tutara göre faiz', ['Yalnızca açılış ücretinin yarısı', 'Hiçbir ücret', 'Tamamı limit kadar sabit faiz'], 'Kredili mevduat hesabında faiz, kullanılan tutar ve süreyle orantılı hesaplanır; kullanılmayan limit için faiz işlemez.'),
  ('Maaşın yarısını kira ve kredi taksitlerine ayırıp geriye kalanla geçinen bir hane, ani 10.000 liralık sağlık harcamasıyla karşılaştığında en olası sorun nedir?', 'Borçlanma ihtiyacı doğar', ['Faiz oranı otomatik olarak düşer', 'Vergi iadesi gelir', 'Banka harcamayı karşılar'], 'Sabit giderleri yüksek, birikimi olmayan hanelerin tampon alanı yoktur; beklenmedik harcamalar borçla karşılanır.'),
  ('Aylık net 50.000 lira geliri olan bir kişi 6 aylık acil durum fonunu zorunlu giderlerin 24.000 lira olduğu varsayımıyla 12 ayda oluşturmak istiyor. Aylık ayırması gereken tutar (faizsiz) kaçtır?', '12.000 lira', ['24.000 lira', '6.000 lira', '14.400,00 lira'], 'Fon hedefi 6 × 24.000 = 144.000 liradır; 12 aya bölünce aylık 12.000 lira gerekir.'),
  ('Bir kişinin kredi kartıyla akşam yaptığı alışveriş tutarının henüz ekstreye yansımadığı halde kullanılabilir limitinden düşmesi hangi işlemle ilgilidir?', 'Provizyon', ['Reeskont', 'Temettü ödemesi', 'Stopaj'], 'Kartlı harcamada banka işlem tutarını önce provizyon olarak limitten ayırır; işlem kesinleşince ekstreye yansır.'),
  ('Vadeli mevduat hesabında vade sonunda "otomatik yenileme" seçeneği açıksa hangi risk doğabilir?', 'Yeni faiz daha düşük olabilir', ['Anaparanın hiç ödenmemesi', 'Hesabın kendiliğinden kapanması', 'Faiz oranının her zaman artması'], 'Otomatik yenilemede yeni vade, yenileme günündeki faiz tarifesiyle başlar; oran düşmüşse getiri azalır.'),
  ('Müşterek (ortak) hesapta ortaklardan birinin hesaptaki paranın tamamını çekmesi riskine karşı hangi önlem alınabilir?', 'Birlikte işlem şartı', ['Şifrenin kısaltılması', 'Hesapta hiç para tutulmaması', 'Hesabın vergiden muaf olması'], 'Birlikte işlem şartı, her işlem için ortakların onayını gerektirir; böylece tek kişi tek başına büyük çekim yapamaz.'),
  ('Bir mağazanın "taksitli satışta vade farkı uygulanmaz" ilanı yaptığı halde taksitli fiyatın peşin fiyattan yüksek olması neyi gösterir?', 'Farkın fiyata dahil edilmesini', ['Taksitli satışın bedava olduğunu', 'Peşin fiyatın yasa dışı olduğunu', 'Ürünün vergiden muaf olduğunu'], 'Taksitli ve peşin fiyat arasındaki fark, ismi "faiz" olmasa da vade farkıdır; tüketici toplam bedeli karşılaştırmalıdır.'),
  ('Birden fazla bankada küçük bakiyeli çok sayıda hesap bulunduran kişi hangi sorunla karşılaşabilir?', 'Ücretler ve takip zorluğu', ['Faiz oranının sıfırlanması', 'Hesapların vergiden muaf olması', 'Ücretlerin kalkması'], 'Çok sayıda hesapta sabit ücretler birikir ve bakiyeler izlenemez; sade bir hesap yapısı genellikle daha ucuz ve takibi kolaydır.'),
  ('Eşit taksitli kredi taksit formülünde faiz oranı yükselirse (anapara ve vade sabit) taksit nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Sıfıra yaklaşır'], 'Daha yüksek oranda anaparanın bedeli artar ve her ay ödenecek sabit taksit yükselir.'),
  ('Jacob Bernoulli 1683\'te sürekli bileşik faizi incelerken hangi matematiksel sabite ulaşmıştır?', 'e sayısına', ['π sayısına', 'Altın orana', 'Avogadro sayısına'], 'Bernoulli, anaparanın aralıksız bileşiklendiği limit durumda (1 + 1/n)ⁿ ifadesinin yaklaşık 2,718\'e yaklaştığını fark etti; bu sabit e olarak bilinir.'),
  ('Luca Pacioli\'nin 1494 tarihli Summa de arithmetica kitabında yer aldığı bilinen ve yatırımın ikiye katlanma süresini yaklaşık hesaplayan pratik kural hangisidir?', '72 kuralı', ['50/30/20 kuralı', '28/36 kuralı', '100 eksi yaş kuralı'], 'Pacioli\'nin eserinde, faiz oranı bölü 72\'nin ikiye katlanma süresini yaklaştırdığı kural ilk kez yazılı olarak geçer.'),
  ('50/30/20 bütçe ilkesini geniş kitlelere duyuran "All Your Worth" kitabının yazarlarından biri kimdir?', 'Elizabeth Warren', ['Adam Smith', 'Irving Fisher', 'Franco Modigliani'], 'Elizabeth Warren ve Amelia Warren Tyagi, 2005 tarihli kitaplarında geliri ihtiyaçlara yüzde 50, isteklere yüzde 30, birikim ve borca yüzde 20 olarak bölen kuralı yaygınlaştırdı.'),
  ('Çocuk adına açılan birikim hesabının uzun vadede faydası için en önemli etken hangisidir?', 'Erken başlayıp düzenli katkı yapmak', ['Katkıyı yalnızca son yılda yapmak', 'Hesabı sık sık kapatıp açmak', 'Katkı yapmayıp getirinin gelmesini beklemek'], 'Bileşik getiride zaman en güçlü etkendir; erken ve düzenli katkı büyük birikimi mümkün kılar.'),
  ('Üniversiteye başlayan bir gencin ilk kredi kartı kullanımında en güvenli başlangıç yaklaşımı hangisidir?', 'Düşük limitli kart; ekstreyi tam ödemek', ['Yüksek limitli birkaç kart alıp asgari ödeme yapmak', 'Kartı hiç ödememek', 'Kartı arkadaşlara kullandırmak'], 'Düşük limit ve tam ödeme, borç tuzağını önlerken kredi geçmişi oluşturmaya yardımcı olur.'),
  ('Yarı zamanlı çalışan bir öğrencinin yıllık geliri vergi muafiyeti sınırının altındaysa genel durum nedir?', 'Vergi ödemeyebilir', ['Her zaman yüzde 50 vergi öder', 'Hiçbir zaman gelir elde edemez', 'Vergiyi ayrıca bankaya yatırır'], 'Düşük gelirler ilk vergi diliminin altında kalıyorsa vergi doğmayabilir ya da kesinti yapıldıysa yıllık beyanla mahsup ve iade talep edilebilir.'),
  ('Küçük işletme sahibi bir kişinin işletme parası ile aile bütçesini ayrı hesaplarda tutmasının başlıca faydası nedir?', 'Net izleme', ['Vergiyi sıfırlamak', 'Banka faizini artırmak', 'Kredi limitini artırmak'], 'Para karışırsa hem işletme kârlılığı hem de hane bütçesi izlenemez; ayrı hesaplar şeffaflık sağlar.'),
  ('Hane bütçesinde elektrik ve su faturalarını düşürmek için yalıtım yapmanın bütçe açısından en önemli özelliği nedir?', 'Yıllarca süren fatura tasarrufu', ['Fatura ödemelerini hemen sıfırlaması', 'Vergi borcunu kapatması', 'Enflasyonu durdurması'], 'Yalıtım gibi enerji tasarruf yatırımları başta maliyetlidir ama aylık giderleri uzun süre azaltarak kendini amorti eder.'),
  ('Gelirinin yetmediği bir ay yoksulluk kıskacında olan bir kişi, borçlarının ödeme sırasını belirlerken hangisini öncelikli tutmalıdır?', 'Temel yaşam giderlerini', ['Lüks tüketim harcamalarını', 'Tatil planı taksitlerini', 'Eğlence aboneliklerini'], 'Önce temel yaşam giderlerinin sürekliliği korunmalı; ardından en yüksek faizli borçlar ve gecikme riski yüksek yükümlülükler gelir.'),
  ('Kredi sözleşmesini imzalamadan önce tüketicinin ön bilgilendirme formunda özellikle kontrol etmesi gereken bilgi hangisidir?', 'Yıllık maliyet oranı, toplam geri ödeme tutarı ve erken kapama koşulları', ['Bankanın kuruluş yıldönümü ve logosu', 'Şube müdürünün adı ve soyadı bilgisi', 'Şubedeki personel sayısı ve çalışma saatleri'], 'Maliyeti ve çıkış şartlarını belirleyen bu kalemler, kredinin gerçek bedelini ve esnekliğini gösterir.'),
  ('Kredi sözleşmesinde küçük puntolarla yazılmış ek ücret ve sigorta şartlarını fark eden tüketicinin yapması gereken en doğru şey nedir?', 'Toplam maliyeti hesaplamak', ['Okumadan imzalamak', 'Şartları reddetmeden kredi çekmek', 'Yalnızca taksit tutarına bakmak'], 'Gizli ya da anlaşılmayan maliyetler toplam bedeli artırır; imzadan önce açıklama istemek hak ve sorumluluktur.'),
  ('Paylaşım ekonomisi uygulamalarında (araç, ev, alet paylaşımı) tüketici bütçesine katkı nasıl açıklanır?', 'Sabit gideri azaltmak', ['Mülkiyeti kalıcı olarak artırma', 'Faiz geliri sağlama', 'Vergi borcunu silme'], 'Paylaşım, nadiren kullanılan varlıklarda sabit maliyetleri çok kişiye yayar ve kişi başına gideri düşürür.'),
  ('Bir finansal teknoloji uygulaması kullanmadan önce kullanıcı hangi kontrolü yapmalıdır?', 'Lisanslı olup olmadığını', ['Yalnızca simgenin güzelliğini', 'İndirme sayısının yüksekliğini', 'Reklam tekrarını'], 'Lisanslı ve denetimli kurumlar, kullanıcının paraları ve verileri için hukuki güvence sağlar.'),
  ('İşçinin maaşından yapılan SGK primi işçi payı ile işsizlik sigortası primi oranları toplamı (brüt üzerinden) kaçtır?', 'Yüzde 15', ['Yüzde 14,5', 'Yüzde 20', 'Yüzde 9'], 'İşçi SGK primi yüzde 14, işsizlik sigortası primi yüzde 1\'dir; toplam kesinti brüt ücretin yüzde 15\'idir.'),
  ('Büyük indirim dönemlerinde (örneğin kara cuma) gerçek indirim olup olmadığını anlamak için tüketici ne yapabilir?', 'Geçmiş fiyatı karşılaştırabilir', ['İlk gördüğü fiyata her zaman güvenebilir', 'Ürünün rengine bakabilir', 'Mağazanın adının uzunluğunu inceleyebilir'], 'Bazı satıcılar indirimden önce fiyatı artırır; geçmiş fiyat bilgisiyle gerçek tasarruf kontrol edilebilir.'),
  ('Üç kredi kartı limiti 50.000, 30.000 ve 20.000 lira ve borçlar sırasıyla 20.000, 15.000 ve 5.000 liradır. Toplam limit kullanım oranı yüzde kaçtır?', 'Yüzde 40', ['Yüzde 30', 'Yüzde 50', 'Yüzde 75\'e yakın'], 'Toplam borç 40.000, toplam limit 100.000 liradır; kullanım oranı yüzde 40\'tır. Kredi değerlendirmesinde genellikle bu oran düşük olmalıdır.'),
  ('120.000 liralık kredinin yıllık maliyet oranını düşürmek isteyen bir kişi, 12 yerine 24 ay vadeli teklifi seçerse hangi iki sonuç birlikte doğar?', 'Taksit düşer, toplam faiz artar', ['Taksit artar, toplam faiz artar', 'Taksit düşer, toplam faiz düşer', 'Taksit artar, toplam faiz daha da düşer'], 'Daha uzun vade aylık yükü azaltır, ancak anapara daha uzun süre borçta kalır; toplam faiz maliyeti yükselir.'),
  ('800.000 liralık bir aracı yüzde 5 peşin iskontoyla 760.000 liraya alabilen ya da 24 ay aylık yüzde 2 faizli kredi kullanan (toplam geri ödeme yaklaşık 1.015.125 lira) bir kişi için krediyle almanın peşine göre ek maliyeti yaklaşık nedir?', 'Yaklaşık 255.000 lira', ['Yaklaşık 40.000 lira', 'Yaklaşık 215.000,00 lira', 'Yaklaşık 800.000 lira'], 'Krediyle toplam ödenen yaklaşık 1.015.125, peşinde ödenen 760.000 liradır; fark 255.125 liradır. Bu fark iskonto kaybı ve faiz yükünün toplamıdır.'),
  ('Kredi kartı ile 12.000 liralık alışveriş yapıp faizsiz 6 taksite bölen bir kişi, taksit tutarını bilinen bir tüketici hakkı kapsamında iade durumunda nasıl bir sonuçla karşılaşır?', 'Taksitler iptal edilir', ['Taksitler yine de tamamen ödenir', 'Faiz iki katına çıkar', 'Hesap otomatik kapanır'], 'Satıcı iadeyi onayladığında banka kalan taksitleri iptal eder ya da ödenmiş kısmı iade eder; böylece tüketici ürünle ilgili bedeli ödemez.'),
  ('Komisyonla kazanan bir finansal danışmanın belirli bir ürünü önermesi karşısında tüketicinin akılda tutması gereken risk nedir?', 'Danışmanın satıştan çıkarı olduğu için tarafsızlık riski', ['Danışmanın tavsiyesinin her zaman en ucuz ürünü gösterdiği', 'Komisyonun vergiden düşülmesi', 'Tavsiyenin hiçbir riskinin olmaması'], 'Komisyon sistemi çıkar çatışması doğurabilir; danışmanın ücret yapısını sormak ve alternatifleri karşılaştırmak gerekir.'),
  ('Sabit ücretli çalışan bir finansal danışmanın ücret yapısının komisyonculuğa göre sağladığı olası fayda nedir?', 'Çıkar çatışmasını azaltması', ['Tavsiyelerin her zaman daha kârlı olması', 'Vergi ödenmemesi', 'Piyasaları tahmin etmesi'], 'Ücret ürün satışına bağlı olmadığında danışmanın müşteri yararına tarafsız davranma ihtimali artar; kesinlik garanti etmez.'),
  ('Kripto girişimine yönelik "geliştiricinin birden fazla yatırımcının parasını toplayıp projeyi bırakıp kaçması" dolandırıcılığına ne ad verilir?', 'Rug pull', ['Reeskont', 'Kayıtlı sermaye', 'Hasarsızlık indirimi'], 'Rug pull\'da kurucular yatırımcı fonlarını çekip projeyi terk eder; denetimsiz yeni projelerde yaygın bir risktir.'),
  ('Kişisel enflasyonu yüzde 40 olan bir çalışan alım gücünü korumak için maaşında en az yaklaşık yüzde kaç zam istemelidir?', 'Yaklaşık yüzde 40', ['Yaklaşık yüzde 20', 'Yaklaşık yüzde 10', 'Yaklaşık yüzde 80\'e yakın'], 'Alım gücü sabit kalsın diye zam, fiyat artışı kadar olmalıdır; yüzde 40\'lık zam reel maaşı korur.'),
  ('Kart borcunu daha düşük faizli bir karta aktaran kişi (bakiye transferi) hangi gizli maliyete dikkat etmelidir?', 'Transfer ücreti', ['Hiçbir ek maliyet yoktur', 'Kredi notunun mutlaka artması', 'Anaparanın silinmesi'], 'Bakiye transferlerinde ücret ve kampanya süresi sonrasında normal faiz uygulanabilir; toplam maliyet hesaplanmalıdır.'),
  ('Bir aile aylık 6.000 lira birikim yapıyor. Bu birikimin yarısını hisse fonuna, yarısını mevduata yatırırsa bunun yönetim gerekçesi nedir?', 'Riski dağıtıp denge kurmak', ['Vergiyi sıfırlamak', 'Garantili yüksek getiri elde etmek', 'Tüm riski ortadan kaldırmak'], 'Güvenli ve riskli araçların birlikte kullanılması dalgalanmayı yumuşatır; amaç riski dağıtmaktır, risksizlik değildir.'),
  ('Bir kişi "paramı bugün harcamazsam yarın daha çok şey alırım" mantığıyla birikim yapıyor; bu mantığın geçerli olması için gerekli koşul hangisidir?', 'Getirinin enflasyonu aşması', ['Faizin sıfır olması', 'Enflasyonun çok yüksek olması', 'Vergilerin artması'], 'Birikim ancak getirisi fiyat artışını aşarsa ileride daha çok mal almayı sağlar; aksi halde alım gücü düşer.'),
  ('Aylık 3.000 lira birikim yapan kişi yıl sonunda tüm birikimiyle ikinci el bir araç almak yerine acil durum fonunu önceliklendirirse bu karar neyi gösterir?', 'Güvenliği öne almayı', ['Vergiden kaçınmayı', 'Enflasyonu önlemeyi', 'Borçlanmayı artırmayı'], 'Acil durum fonu beklenmedik risklere karşı tampon sağlar; öncelik bu tampona verildiğinde borçlanma ihtiyacı azalır.'),
  ('Aynı kredi tutarında iki teklif: A %2,2 faiz, 3 ay ödemesiz; B %2,2 faiz, ödemesiz dönem yok. Faiz ödemesiz dönemde de işliyorsa hangisi daha pahalıdır?', 'A; ödemesizde faiz de işler', ['B; çünkü ödemesiz dönem yoktur', 'İkisi aynıdır', 'A; çünkü faiz yalnızca B\'de işler'], 'Ödemesiz dönemde faiz bileşik işlerse toplam geri ödeme artar; ödemesiz dönem faizsiz demek değildir.'),
  ('Kredi kartı kullanımında yüksek limitin gereksiz harcamayı artırabileceğini düşünen kişi hangi önlemi alabilir?', 'Limiti düşürtmek', ['Limiti sürekli yükseltmek', 'Kartı herkesle paylaşmak', 'Ekstreyi okumamak'], 'Düşük limit ve anlık bildirim harcamayı görünür ve sınırlı kılar; dürtüsel borçlanmayı azaltır.'),
  ('Gelirinin yüzde 50\'si tek bir işverenden gelen ve işverenin iflas riski yüksek olan biri için gelir çeşitlendirmesi neden önerilir?', 'Riski azaltmak için', ['Vergiyi sıfırlamak için', 'Faiz getirisini artırmak için', 'Maaşı iki kat yapmak için'], 'Farklı gelir kaynakları, bir kaynağın kesilmesi durumunda toplam gelirin tamamen kaybolmasını önler.'),
  ('İş değiştirmek isteyen bir çalışan için yeni işteki maaş artışı kadar hangi faktör de karşılaştırılmalıdır?', 'Yan haklar ve iş güvencesi', ['Yalnızca şirketin adının uzunluğu', 'Yalnızca ofisin rengi', 'Yalnızca masa sayısı'], 'Karar nakit maaşla sınırlı olmamalı; ulaşım maliyeti, sosyal haklar ve güvenlik toplam faydayı belirler.'),
  ('Finansal önceliklendirmede sık önerilen sıralamaya göre acil durum fonu, yüksek faizli borç kapatma ve uzun vadeli yatırım arasında hangisi ilk sıraya konur?', 'Acil fon ve borç kapatma', ['Uzun vadeli riskli yatırım', 'Lüks tüketim', 'Yeni kredi çekmek'], 'Beklenmedik giderler borçla karşılanmasın diye önce küçük bir tampon, ardından yüksek faizli borçlar kapatılır; sonra uzun vadeli hedeflere geçilir.'),
  ('Beklenmedik 80.000 liralık bir ikramiye alan, ancak yıllık yüzde 60 faizli kart borcu olan biri için en rasyonel kullanım hangisidir?', 'Kart borcunu kapatmak', ['Parayı lüks tüketimde harcamak', 'Tamamını vadesiz hesapta bekletmek', 'Yeni bir kart açtırmak'], 'Yüzde 60 faizli borcu kapatmak, garantili ve çok yüksek getiriye eşdeğerdir; bu getiri çoğu yatırımdan yüksektir.'),
  ('Kredi başvurusu reddedilen biri reddin nedenini öğrenip hangi adımı atmalıdır?', 'Nedeni giderip yeniden başvurmak', ['Hemen çok sayıda başka bankaya başvurmak', 'Hiçbir adım atmamak', 'Sahte belge sunmak'], 'Reddin gerekçesi (düşük not, yüksek borç, eksik belge) giderilirse başarı şansı artar; ardışık başvurular notu daha da düşürebilir.'),
  ('Konut kredisine başvurmadan önceki 6 ayda finansal olarak hazırlanmak isteyen kişi için en yararlı adımlar hangileridir?', 'Borcu azaltıp peşinatı artırmak', ['Yeni kredi kartları açıp limitleri doldurmak', 'Ödemeleri geciktirmek', 'Hesaplarını kapatmak'], 'Düşük borç, düzenli ödeme ve yeterli peşinat, kredi onayı ve faiz teklifi açısından en güçlü sinyallerdir.'),
  ('İlk evini alırken peşinat için 4 yıl biriktirme planı yapan biri, süre boyunca konut fiyatlarının artacağını hesaba katmazsa en olası sorun nedir?', 'Hedefin yetmemesi', ['Faizin sıfırlanması', 'Vergi iadesi', 'Borç silinmesi'], 'Konut fiyatı artarsa peşinat hedefi de yükselir; hedefte enflasyon ve fiyat artışı dikkate alınmalıdır.'),
  ('İş kaybı yaşayan bir hane için ilk kısa vadeli finansal adım olarak aşağıdakilerden hangisi önerilir?', 'Giderleri kısıp acil fonu kullanmak', ['Yeni kredi kartları almak', 'Yüksek taksitli lüks alışveriş yapmak', 'Ödemeleri tamamen bırakmak'], 'Gelir kesildiğinde gider yönetimi ve birikim kullanımı önceliklidir; borçlanmak sorunu büyütebilir.'),
  ('Bir kredi kartının yıllık aidatı 600 lira, ödediği faiz yıllık 4.800 lira, kazandığı puan geliri 900 liradır. Kartın yıllık net maliyeti kaç liradır?', '4.500 lira', ['5.400 lira', '600 lira', '3.900,00 lira'], 'Maliyet 600 + 4.800 = 5.400 liradır; puan geliri 900 lira düşünce net maliyet 4.500 lira olur.'),
  ('Mevsimlik çalışan bir kişi yıl boyunca 12 ay gelir elde edemediği için hangi finansal uygulamayı daha çok önemser?', 'Bir tampon fon oluşturmayı', ['Her ay gelirini harcamayı', 'Tüm geliri tek ay içinde harcamayı', 'Hiç birikim yapmamayı'], 'Mevsimlik gelir düzensiz olduğundan fazla aylardan ayrılan fon, gelirsiz aylarda gider karşılamak için gerekli tampondur.'),
  ('Aynı faiz oranı ve vadede, anaparası daha yüksek bir kredinin toplam faiz maliyeti ve taksiti anaparası düşük krediye göre nasıl olur?', 'Her ikisi de artar', ['Taksit düşer, toplam faiz artar', 'Taksit artar, toplam faiz değişmez', 'Taksit ve faiz değişmez'], 'Taksit ve toplam faiz anaparayla doğru orantılıdır; anapara iki katına çıkarsa her ikisi de yaklaşık iki katına çıkar.'),
  ('Mevduat faizinden yapılan stopaj kesintisinin, yatırımcının aynı brüt oran ve vadeli iki üründen birinde diğerinden farklı olması halinde karar kriteri ne olmalıdır?', 'Net getiri', ['Yalnızca brüt oran', 'Yalnızca bankanın adı', 'Yalnızca şube sayısı'], 'Aynı brüt getiri farklı vergi oranlarıyla farklı net getiri verir; kararlar net getiriye göre verilmelidir.'),
  ('Hem yıllık enflasyon hem aylık faiz verilen bir sorunda aynı birimde karşılaştırma yapmak neden gereklidir?', 'Farklı sürelerin kıyası yanıltıcıdır', ['Oranlar her zaman aynı süreyi ifade eder', 'Karşılaştırma yasaktır', 'Birim önemsizdir'], 'Aylık ve yıllık oranlar aynı süreye çevrilmeden karşılaştırılamaz; bileşik etki nedeniyle çevrim 12 ile çarpmakla değil üs alarak yapılır.'),
  ('Kıdem tazminatı hakkı doğmadan işten ayrılan kişi için aşağıdakilerden hangisi doğrudur?', 'Sebepsiz istifada hak doğmaz', ['Her istifada kıdem tazminatı ödenir', 'Tazminat yalnızca zam durumunda ödenir', 'Tazminat bankadan alınır'], 'Kıdem tazminatı işveren feshi, haklı fesih, emeklilik gibi kanunda sayılan durumlarda doğar; sebepsiz istifa bunlardan değildir.'),
  ('Sigorta poliçesi yenileme döneminde primi düşük teklif veren yeni bir şirkete geçmeden önce karşılaştırılması gereken en önemli kalem nedir?', 'Teminat ve muafiyet', ['Şirket binası rengi', 'Reklamın süresi', 'Şirket logosunun büyüklüğü'], 'Düşük prim daha dar teminat ya da yüksek muafiyet anlamına gelebilir; fiyat tek başına yeterli ölçüt değildir.'),
  ('Gelir seviyesi yükselen bir kişinin birikimini artırmasında "sabit oranlı otomatik artırma" yöntemi neyi sağlar?', 'Zamla birikim tutarı artar', ['Giderlerin otomatik silinmesi', 'Faizin sıfırlanması', 'Vergi oranının düşmesi'], 'Birikim oranı sabit tutulursa gelir arttıkça birikim tutarı da büyür; bu yöntem yaşam tarzı şişmesini engeller.'),
  ('Hesabındaki parayı hiç değerlendirmeden vadesiz hesapta tutan ve aynı zamanda yüksek faizli kredi kartı borcu olan kişi için en mantıklı hamle nedir?', 'Borcu kısmen kapatmak', ['Parayı hiç kullanmamak', 'Daha fazla borçlanmak', 'Kartı iki katına çıkarmak'], 'Düşük getirili vadesiz hesaptaki para, yüksek faizli borcu kapatmakta daha çok değer yaratır; küçük bir acil fon bırakılmalıdır.'),
  ('Bir kişi yıllık enflasyonun yüzde 30 olduğu bir ortamda yüzde 30 yıllık sabit faizli kredi çekip enflasyon beklentisinden fazla bir artış yaşanırsa ne olur?', 'Reel maliyet düşer', ['Kredinin reel maliyeti artar', 'Reel maliyet değişmez', 'Banka borcu siler'], 'Sabit faizli borçta enflasyon beklenenden yüksek gelirse reel faiz beklenenden düşük çıkar ve alacaklı aleyhine bir transfer olur.'),
  ('Mevduat faizi yüksek göründüğü halde stopaj ve enflasyon sonrası reel getirisi negatif olan bir ürüne yatırım yapan kişi hangi yanılgıya düşer?', 'Nominal getiriyi gerçek getiri sanmak', ['Yüksek vergiyi avantaj saymak', 'Enflasyonu sıfır kabul etmek zorunda kalmak', 'Faizin geri ödeneceğini düşünmek'], 'Nominal oranlar alım gücü kaybını göstermez; reel getiri enflasyon ve vergi düşülerek hesaplanır.'),
];
